WITH bundle AS (SELECT '[{"id":"c8202611-05b0-4a9b-9f00-000000000001","title":"生活理财：从零花钱到预算","subject":"生活理财","grade_level":"Year 6","language":"zh","description":"20 道原创生活理财题，学习预算、储蓄、消费者权益与消费判断。","questions":[{"question":"小明每周有 RM20 零花钱，花 RM12 后还剩多少？","options":["RM8","RM6","RM10","RM12"],"correct_option_index":0,"explanation":"RM20 减去 RM12，剩下 RM8。"},{"question":"“预算”最主要的用途是什么？","options":["保证每次购物打折","让钱自动增加","避免记录花费","提前规划收入与支出"],"correct_option_index":3,"explanation":"预算帮助安排有限资金的用途。"},{"question":"你有 RM50，想买 RM35 的书和 RM20 的玩具，最合理的做法是？","options":["向陌生人借钱","不看价格直接付款","先按需要选择并核算总价","两件都买不用计算"],"correct_option_index":2,"explanation":"两件共 RM55，超出预算 RM5。"},{"question":"哪一种行为属于“储蓄”？","options":["不记得钱放在哪里","把部分零花钱留作日后使用","把全部钱当天花完","借钱买不需要的东西"],"correct_option_index":1,"explanation":"储蓄是把当前资源保留给未来。"},{"question":"“需要”和“想要”有什么区别？","options":["需要是基本必要，想要是额外愿望","两者完全一样","想要永远更重要","需要只指玩具"],"correct_option_index":0,"explanation":"区分必要支出和可选消费能改善预算。"},{"question":"商品标价 RM24，折扣 RM4，实付多少？","options":["RM28","RM22","RM16","RM20"],"correct_option_index":3,"explanation":"实付价格为原价减优惠额。"},{"question":"两家商店同款笔分别卖 RM3 和 RM5，哪家更便宜？","options":["两家一样","不能比较","RM3 的商店","RM5 的商店"],"correct_option_index":2,"explanation":"在质量和条件相同时，RM3 比 RM5 便宜。"},{"question":"“收据”一般可以帮助你做什么？","options":["让商品永远不损坏","核对付款记录与购买凭证","自动增加银行余额","代替所有身份证明"],"correct_option_index":1,"explanation":"收据是交易记录，退换货时也可能有用。"},{"question":"看到“限时五分钟立刻付款”的广告，你应该先怎样做？","options":["比较价格并确认是否真的需要","立即付款不考虑","把密码交给卖家","相信所有倒计时"],"correct_option_index":0,"explanation":"倒计时可能制造冲动消费压力。"},{"question":"什么是“利息”？","options":["商品包装颜色","一张购物清单","固定不变的折扣","借贷或存款可能涉及的资金使用成本或回报"],"correct_option_index":3,"explanation":"利息通常按本金、利率和时间计算。"},{"question":"想存 RM60，每周存 RM10，大约需要几周？","options":["7 周","10 周","6 周","5 周"],"correct_option_index":2,"explanation":"RM60 ÷ RM10 = 6 周。"},{"question":"为什么不应随意分享银行卡密码？","options":["有助于获得免费礼物","可能让别人未经许可使用账户","会让银行卡变轻","能增加存款利息"],"correct_option_index":1,"explanation":"银行卡密码属于敏感的金融验证信息。"},{"question":"现金付款和电子付款有什么共同点？","options":["都应该核对实际支付金额","都不需要保护隐私","都不会发生错误","都可以无限支付"],"correct_option_index":0,"explanation":"无论支付方式，都需要确认金额与收款对象。"},{"question":"如果商品出现质量问题，最实用的第一步是什么？","options":["立即公开所有个人资料","丢弃所有收据","随意转账给陌生客服","保存凭证并联系合法销售渠道"],"correct_option_index":3,"explanation":"保留证据有助于与商家沟通。"},{"question":"“单价”可以帮助你比较什么？","options":["商店音乐好不好听","广告字体大小","不同包装的单位成本","商品颜色是否好看"],"correct_option_index":2,"explanation":"单位价格可以比较每克或每件的成本。"},{"question":"同样的饮料，250 mL 售 RM2，500 mL 售 RM3，哪个每毫升更划算？","options":["无法判断","500 mL 售 RM3","250 mL 售 RM2","两者单位价格一样"],"correct_option_index":1,"explanation":"每毫升分别为 RM0.008 和 RM0.006。"},{"question":"什么是“紧急备用金”？","options":["留给意外必要支出的储蓄","专门买玩具的钱","每天必须花完的钱","任何人的共享密码"],"correct_option_index":0,"explanation":"备用金可以帮助应付突发的合理开支。"},{"question":"购买数字游戏道具前，为什么要先确认费用？","options":["数字商品永远免费","所有付费道具都能退款","付款不需要监护人知道","虚拟购买也可能产生真实支出"],"correct_option_index":3,"explanation":"游戏内购买也会消耗真实资金。"},{"question":"朋友向你推荐“稳赚不赔”的投资，哪种判断更审慎？","options":["公开账户密码","邀请同学一起冲动投资","怀疑保证回报的说法并向可信成年人求证","马上投入全部存款"],"correct_option_index":2,"explanation":"任何投资都有风险，保证高回报的说法值得警惕。"},{"question":"每月记录自己的花费，最大的价值是什么？","options":["确保未来没有意外","发现消费习惯并改进安排","让价格自动下降","避免学习数学"],"correct_option_index":1,"explanation":"记录支出能帮助识别不必要的花费。"}]},{"id":"c8202611-05b0-4a9b-9f00-000000000002","title":"Young Entrepreneurs: Ideas & Customers","subject":"Entrepreneurship","grade_level":"Year 7","language":"en","description":"20 realistic questions about business ideas, customer needs, feedback and simple costs.","questions":[{"question":"What is a business customer?","options":["Only the shop owner","A machine in a factory","An online password","Someone who buys or uses a product or service"],"correct_option_index":3,"explanation":"Customers are people or organisations served by a business."},{"question":"A team wants to sell reusable bottles. What should it learn first?","options":["How to skip safety rules","How to copy every rival logo","Whether customers need and want the bottles","The colour of the founder''s shoes"],"correct_option_index":2,"explanation":"Understanding customer needs helps define a useful product."},{"question":"What does a prototype help a team do?","options":["Remove every design risk","Test an early version of an idea","Guarantee a billion sales","Avoid customer feedback"],"correct_option_index":1,"explanation":"A prototype lets people try and evaluate a concept."},{"question":"What is revenue?","options":["Money received from selling goods or services","Only the money left after expenses","The number of shop chairs","A company''s logo colours"],"correct_option_index":0,"explanation":"Revenue is sales income before subtracting expenses."},{"question":"What is a cost to a small bakery?","options":["A customer compliment","A social media follower","A product review","Ingredients used to make bread"],"correct_option_index":3,"explanation":"Ingredients are resources the bakery pays for."},{"question":"A school stall sells ten bookmarks for RM3 each. What is total sales revenue?","options":["RM7","RM33","RM30","RM13"],"correct_option_index":2,"explanation":"Ten multiplied by RM3 equals RM30 in revenue."},{"question":"If revenue is RM30 and total expenses are RM18, what is the simple profit?","options":["RM30","RM12","RM48","RM18"],"correct_option_index":1,"explanation":"Profit is revenue minus expenses, here RM12."},{"question":"Why should a startup ask users for feedback?","options":["To learn what actually works and what needs improvement","To prove its first idea is always perfect","To collect unnecessary passwords","To avoid future changes"],"correct_option_index":0,"explanation":"User feedback helps identify problems and improvements."},{"question":"What is a value proposition?","options":["An automatic bank transfer","A list of all employee birthdays","A random slogan without meaning","A clear explanation of how a product helps customers"],"correct_option_index":3,"explanation":"A value proposition states the benefit a customer can expect."},{"question":"Which is an ethical way to promote a product?","options":["Hide important charges","Claim untested medical benefits","Describe its real features accurately","Invent positive reviews"],"correct_option_index":2,"explanation":"Accurate claims support customer trust."},{"question":"A competitor offers a similar product. What should a founder do?","options":["Copy their private customer list","Understand differences and improve their own offer","Steal their accounts","Publish false rumours"],"correct_option_index":1,"explanation":"Fair competition focuses on genuine customer value."},{"question":"What does a break-even point describe?","options":["The level where revenue covers costs","A moment when no product can be sold","A fixed discount of 50 percent","When a shop closes every day"],"correct_option_index":0,"explanation":"At break-even, total revenue equals total costs."},{"question":"Why does accessibility matter for a student app?","options":["It always increases the price","It prevents all bugs","It replaces customer support","More people can use it despite different abilities"],"correct_option_index":3,"explanation":"Accessible design reduces unnecessary barriers."},{"question":"What is a recurring customer?","options":["A supplier of electricity","An imaginary user","A customer who returns to buy or use a service again","A person visiting once"],"correct_option_index":2,"explanation":"Returning users can indicate continuing usefulness."},{"question":"What should a team do with a failed prototype?","options":["Ignore the evidence","Identify the cause and revise the design","Pretend the test never happened","Immediately blame users"],"correct_option_index":1,"explanation":"Failure information supports iteration."},{"question":"What is a partnership in a project?","options":["Two parties cooperating toward agreed goals","One person secretly using another''s brand","A promise of guaranteed profit","An automatic legal registration"],"correct_option_index":0,"explanation":"A partnership is cooperation based on an agreed purpose."},{"question":"Why track simple business metrics?","options":["To make graphs look impressive only","To replace product quality","To avoid talking to customers","To observe progress against a goal"],"correct_option_index":3,"explanation":"Useful metrics help identify changes over time."},{"question":"A customer reports a real problem. Which response is best?","options":["Mock the customer publicly","Invent a technical excuse","Listen, investigate and communicate a resolution","Delete the message without reading"],"correct_option_index":2,"explanation":"Respectful support and investigation can resolve issues."},{"question":"Why should product prices be transparent?","options":["Only the seller should know the cost","Customers need to understand what they will pay","Hidden charges build trust","Prices have no effect on decisions"],"correct_option_index":1,"explanation":"Clear pricing supports informed choices."},{"question":"A business idea collects students'' personal data. What should the team prioritize?","options":["Collect only necessary data and protect it","Publish every student''s address","Sell private data without permission","Use the same password for all staff"],"correct_option_index":0,"explanation":"Privacy should be built into the product from the beginning."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000003","title":"Media Detectives: Facts & Misinformation","subject":"Media Literacy","grade_level":"Year 7","language":"en","description":"20 media literacy scenarios about sources, misleading posts, social networks and verification.","questions":[{"question":"A viral post has no named source. What is a sensible first step?","options":["Assume popularity proves truth","Edit it to sound more dramatic","Find an independent trustworthy source","Forward it immediately"],"correct_option_index":2,"explanation":"Popularity is not evidence that a claim is correct."},{"question":"What is a primary source for a speech?","options":["An advertisement for the event","A recording or transcript of the original speech","A stranger''s summary","An unrelated opinion article"],"correct_option_index":1,"explanation":"Primary sources provide direct evidence."},{"question":"What is a headline''s main purpose?","options":["Introduce the subject and attract a reader","Replace the entire article","Guarantee every statement is true","Identify every source automatically"],"correct_option_index":0,"explanation":"A headline summarises or promotes content but cannot replace verification."},{"question":"A photo from 2019 is shared as today''s flood. What is the problem?","options":["Older photos cannot be useful","Photos never show real events","All floods are identical","The image is presented with misleading timing"],"correct_option_index":3,"explanation":"An authentic image can mislead when placed in false context."},{"question":"How can you check whether a photograph is reused elsewhere?","options":["Ask the poster to use more emojis","Assume its caption is accurate","Search for earlier appearances of the image","Count its pixels only"],"correct_option_index":2,"explanation":"Earlier appearances may reveal the photo''s original context."},{"question":"What is an opinion?","options":["An official receipt","A personal judgement that may differ between people","A measurement guaranteed to be exact","A statement always false"],"correct_option_index":1,"explanation":"Opinions express preferences or judgements."},{"question":"Which statement is directly verifiable?","options":["The event begins at 9:00 AM on Saturday","This is the best event ever","The music is wonderful","That poster looks ugly"],"correct_option_index":0,"explanation":"A published schedule can verify a stated starting time."},{"question":"A sponsored post promotes a product. What should viewers recognise?","options":["Advertising makes every claim true","Sponsored content is always illegal","No sponsorship disclosure is ever needed","The creator may have a commercial incentive"],"correct_option_index":3,"explanation":"Sponsorship can affect the motivation behind a message."},{"question":"What is confirmation bias?","options":["Measuring weather accurately","Reading multiple viewpoints fairly","Preferring information that supports existing beliefs","Changing the topic of a report"],"correct_option_index":2,"explanation":"People may selectively notice evidence supporting their views."},{"question":"Why compare reports from multiple independent sources?","options":["It replaces direct observation in every case","It can reveal mistakes and missing context","It guarantees everyone agrees","It removes the need for evidence"],"correct_option_index":1,"explanation":"Independent reporting can improve confidence."},{"question":"What is a deepfake?","options":["Synthetic media made to imitate a real person or event","A very old newspaper","A type of safe backup","A computer cooling system"],"correct_option_index":0,"explanation":"AI-generated video or audio can simulate appearances or voices."},{"question":"A convincing AI voice note asks for money. What is safest?","options":["Pay immediately","Share your banking PIN","Assume the voice cannot be forged","Verify identity through a separate trusted channel"],"correct_option_index":3,"explanation":"Voice recordings can be imitated, so verification matters."},{"question":"What does a citation help readers do?","options":["Hide the original author","Replace all critical thinking","Locate the evidence supporting a claim","Make an article automatically correct"],"correct_option_index":2,"explanation":"Citations let others inspect the source material."},{"question":"Why can a cropped chart be misleading?","options":["Only the colours matter","It may hide important axis values or comparison context","Cropping always improves accuracy","Charts never use numbers"],"correct_option_index":1,"explanation":"Missing scales can exaggerate or minimise differences."},{"question":"An online claim cites ''experts'' but no names or studies. What is missing?","options":["Identifiable evidence that can be checked","An exciting background song","A larger font","More reaction emojis"],"correct_option_index":0,"explanation":"Unspecified authorities are difficult to verify."},{"question":"Which question is useful when reading a news article?","options":["How many colourful icons appear?","Can it make me angry quickly?","Does it have many capital letters?","Who produced it and what evidence supports it?"],"correct_option_index":3,"explanation":"Assessing source and evidence helps evaluate accuracy."},{"question":"What is clickbait?","options":["A verified scientific reference","A school attendance register","A sensational heading designed to attract clicks","Any careful investigative report"],"correct_option_index":2,"explanation":"Clickbait often prioritises clicks over clear context."},{"question":"Which is a responsible way to correct a mistaken post?","options":["Invent a new rumour","Explain the correction and provide reliable evidence","Insult anyone who believed it","Delete every opposing opinion"],"correct_option_index":1,"explanation":"Evidence-based corrections help others update beliefs."},{"question":"Why distinguish a simulation from real footage?","options":["Viewers deserve to know what actually happened","All visual media must be forbidden","Simulations are always useless","Reality can be determined by video quality alone"],"correct_option_index":0,"explanation":"Labels prevent fictional reconstructions from being mistaken for records."},{"question":"A study cited online has only ten participants. What should you consider?","options":["That the conclusion must be universal","That statistics can be ignored","That every small study is fraudulent","Whether the sample size and design support the claim"],"correct_option_index":3,"explanation":"Study design and sample size affect how findings can be interpreted."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000004","title":"Farms, Food Systems & Agriculture","subject":"Agriculture","grade_level":"Year 6","language":"en","description":"20 questions on crops, soil, sustainable farming, pollination and food supply chains.","questions":[{"question":"Why do farmers rotate different crops across seasons?","options":["To avoid harvesting food","To help maintain soil health and manage pests","To make every plant look identical","To prevent all rainfall"],"correct_option_index":1,"explanation":"Crop rotation can reduce some pests and improve nutrient balance."},{"question":"Which plant part usually develops into a fruit after fertilisation?","options":["The flower''s ovary","The root tip","The bark","The stem hair"],"correct_option_index":0,"explanation":"In flowering plants, the ovary commonly develops into a fruit."},{"question":"What is compost?","options":["A type of plastic fertiliser bottle","Only pure sand","An insecticide spray","Decomposed organic material used to enrich soil"],"correct_option_index":3,"explanation":"Compost returns organic matter and nutrients to soil."},{"question":"Why are bees important to many crops?","options":["They replace soil nutrients","They make every plant grow instantly","They move pollen between flowers","They create all rainfall"],"correct_option_index":2,"explanation":"Pollinators enable fertilisation for many flowering plants."},{"question":"Which practice helps conserve irrigation water?","options":["Removing all soil cover","Drip irrigation near plant roots","Leaving hoses running all day","Watering paved roads"],"correct_option_index":1,"explanation":"Drip systems can deliver water efficiently to roots."},{"question":"What does a seed need to germinate in most common crops?","options":["Suitable water, oxygen and temperature","Only bright paint","A metal container","A television signal"],"correct_option_index":0,"explanation":"Seeds typically germinate when conditions are suitable."},{"question":"How do earthworms often help gardens?","options":["They turn soil into plastic","They stop all microbes","They prevent all plant diseases","They improve soil structure as they move and feed"],"correct_option_index":3,"explanation":"Earthworm activity can support soil aeration and nutrient cycling."},{"question":"What is a greenhouse used for?","options":["Blocking all sunlight permanently","Replacing every farm worker","Managing growing conditions for plants","Storing fuel only"],"correct_option_index":2,"explanation":"Greenhouses let growers adjust aspects of the environment."},{"question":"Why should farmers check soil moisture?","options":["To choose the colour of baskets","To decide when plants need watering","To predict the next year''s prices exactly","To measure a tractor''s speed"],"correct_option_index":1,"explanation":"Soil moisture can guide irrigation decisions."},{"question":"What is an invasive pest?","options":["An organism that can harm crops outside its native balance","Every insect on a farm","A plant that gives fruit","A tool for harvesting rice"],"correct_option_index":0,"explanation":"Some introduced organisms cause damage when populations spread."},{"question":"Which crop is especially important as a staple food in Malaysia?","options":["Cocoa butter alone","Olives only","Rye bread alone","Rice"],"correct_option_index":3,"explanation":"Rice is a major staple food in Malaysia."},{"question":"What is a food supply chain?","options":["Only the final supermarket shelf","A type of cooking recipe","The stages from growing food to delivering it to consumers","A metal chain around a field"],"correct_option_index":2,"explanation":"Supply chains involve production, processing, transport and sales."},{"question":"What can happen when harvested vegetables are stored too warm?","options":["They become immune to bacteria","They may spoil more quickly","They become permanently sterile","Their mass always doubles"],"correct_option_index":1,"explanation":"Temperature control helps preserve freshness."},{"question":"What is hydroponics?","options":["Growing plants with nutrient solutions without conventional soil","Growing plants only in snow","Storing seeds in oil","A method of fishing"],"correct_option_index":0,"explanation":"Hydroponics supplies nutrients through water-based growing systems."},{"question":"Why might farmers use mulch around plants?","options":["To remove all oxygen from the air","To grow rocks","To stop sunlight reaching leaves","To reduce evaporation and suppress some weeds"],"correct_option_index":3,"explanation":"Mulch can protect soil moisture and moderate temperature."},{"question":"What is sustainable farming aiming to balance?","options":["Only the colour of fields","Maximum pesticide use always","Food production with long-term environmental and resource care","Harvest size at any environmental cost"],"correct_option_index":2,"explanation":"Sustainable methods aim to protect resources while producing food."},{"question":"Why can monoculture create risk for farms?","options":["It removes all costs","A single crop may be vulnerable to the same pest or disease","It always produces ten crops at once","It prevents every drought"],"correct_option_index":1,"explanation":"Low crop diversity can increase shared vulnerability."},{"question":"What is a natural predator used for in pest management?","options":["Helping control harmful insect populations","Adding salt to all soil","Removing all birds","Turning crops into fuel"],"correct_option_index":0,"explanation":"Biological control can use predators of crop pests."},{"question":"Which food waste practice can help a household garden?","options":["Mixing batteries into soil","Pouring engine oil on plants","Dumping plastic bags","Composting suitable plant scraps"],"correct_option_index":3,"explanation":"Suitable biodegradable scraps can become compost."},{"question":"What is the purpose of farm-to-market transport?","options":["Eliminate the need for packaging in every case","Change plant species","Deliver harvested food to buyers safely and efficiently","Make crops grow without sunlight"],"correct_option_index":2,"explanation":"Transport connects producers to processors, sellers and consumers."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000005","title":"Ocean Explorers: Life Beneath the Waves","subject":"Ocean Science","grade_level":"Year 6","language":"en","description":"20 original ocean questions on tides, reefs, marine life and science.","questions":[{"question":"What covers most of Earth''s surface?","options":["Oceans and seas","Desert dunes","Permanent ice sheets","Rainforests"],"correct_option_index":0,"explanation":"Ocean water covers about seventy-one percent of Earth''s surface."},{"question":"What causes most regular ocean tides?","options":["Wind direction only","Volcanic heat only","Rainfall in one city","The gravitational pull of the Moon, with a contribution from the Sun"],"correct_option_index":3,"explanation":"Lunar gravity dominates most tidal patterns."},{"question":"Why are coral reefs valuable?","options":["They prevent every tsunami","They replace ocean currents","They provide habitat for many marine species","They make all ocean water fresh"],"correct_option_index":2,"explanation":"Complex reefs shelter and support diverse organisms."},{"question":"What is a plankton organism?","options":["A submarine component","A drifting organism carried by water movement","Only a fully grown shark","A permanent rock"],"correct_option_index":1,"explanation":"Plankton includes small plants and animals that drift in water."},{"question":"What is phytoplankton''s role in marine food webs?","options":["It produces organic matter using light","It always eats whales","It destroys all oxygen","It is made of plastic"],"correct_option_index":0,"explanation":"Many phytoplankton species perform photosynthesis."},{"question":"Which zone of the ocean receives the most sunlight?","options":["The deepest trenches","The seabed everywhere","Under volcanic rocks only","Surface waters"],"correct_option_index":3,"explanation":"Light generally decreases as water depth increases."},{"question":"Why does ocean water taste salty?","options":["It has no minerals","It is mixed with sand only","It contains dissolved mineral salts","It is mostly sugar"],"correct_option_index":2,"explanation":"Weathering and other processes supply dissolved salts to the ocean."},{"question":"Which marine animal is a mammal?","options":["Sea star","Dolphin","Tuna","Octopus"],"correct_option_index":1,"explanation":"Dolphins breathe air and nurse their young."},{"question":"How do many fish obtain dissolved oxygen?","options":["Using gills","By growing leaves","Through wheels","By collecting sunlight in fur"],"correct_option_index":0,"explanation":"Fish gills exchange gases with surrounding water."},{"question":"What does a marine protected area try to do?","options":["Ban every research project","Turn seawater into fresh water","Remove all fishing boats worldwide","Conserve ocean habitats and species"],"correct_option_index":3,"explanation":"Protection rules can help preserve marine ecosystems."},{"question":"How can plastic litter affect sea turtles?","options":["Turtles have metal shells","Plastic makes water less salty","Turtles may mistake plastic for food or become entangled","Plastic always turns into food"],"correct_option_index":2,"explanation":"Ingestion and entanglement are serious risks."},{"question":"What is an estuary?","options":["An inland volcano","A place where river water mixes with seawater","A high mountain summit","A desert plateau"],"correct_option_index":1,"explanation":"Estuaries contain a changing mixture of fresh and salt water."},{"question":"Why do mangrove forests help young fish?","options":["Their roots create sheltered nursery habitats","Their roots produce unlimited salt","They stop all ocean waves","They are made only of coral"],"correct_option_index":0,"explanation":"Many juvenile fish use sheltered mangrove waters."},{"question":"What is sonar commonly used for?","options":["Measuring only sunlight","Changing seawater colour","Producing freshwater rain","Using sound waves to detect objects underwater"],"correct_option_index":3,"explanation":"Sound travels well underwater and can reveal submerged objects."},{"question":"What is the deep ocean usually like?","options":["Filled with sunlight at all depths","Completely free of life","Cold, dark and under high pressure","Bright and hot everywhere"],"correct_option_index":2,"explanation":"Deep water has little light and can have high pressure."},{"question":"What are ocean currents?","options":["Kinds of marine plants","Large-scale movements of seawater","Only surface bubbles","Underwater mountain ranges"],"correct_option_index":1,"explanation":"Currents transport water, heat and nutrients."},{"question":"What is a sustainable seafood choice concerned with?","options":["Avoiding unnecessary harm to fish populations and habitats","Buying only the biggest fish","Ignoring fishing methods","Catching every juvenile fish"],"correct_option_index":0,"explanation":"Fishing practices affect marine ecosystems and future stocks."},{"question":"Why can fertiliser runoff damage coastal water?","options":["Nutrients always remove algae","It makes all water drinkable","It stops tides","Excess nutrients may trigger harmful algal blooms"],"correct_option_index":3,"explanation":"Too many nutrients can cause blooms and oxygen problems."},{"question":"What is a scientific use of an underwater robot?","options":["Make waves disappear","Change the Earth''s gravity","Explore places difficult or dangerous for divers","Replace every marine animal"],"correct_option_index":2,"explanation":"Remotely operated vehicles collect images and measurements."},{"question":"How can students help protect nearby beaches?","options":["Damage coastal plants","Take litter home and join safe clean-up efforts","Leave fishing lines in the sand","Release plastic packaging into the sea"],"correct_option_index":1,"explanation":"Reducing litter helps protect coastal habitats."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000006","title":"Engineering Workshop: Build & Test","subject":"Engineering","grade_level":"Year 7","language":"en","description":"20 engineering design and physics questions about structures, testing and inventions.","questions":[{"question":"What is the first useful step in an engineering project?","options":["Buy random materials","Paint the final model","Skip all safety planning","Define the problem and requirements"],"correct_option_index":3,"explanation":"Clear requirements guide a practical design."},{"question":"Why do engineers build models?","options":["To avoid understanding forces","To replace every measurement","To test ideas before constructing full-size designs","To guarantee no mistakes"],"correct_option_index":2,"explanation":"Models help reveal strengths and weaknesses."},{"question":"Why are triangles common in bridge trusses?","options":["They cannot ever bend","They can form rigid structures that distribute loads","They remove the need for materials","They produce electricity automatically"],"correct_option_index":1,"explanation":"Triangular geometry can improve structural stability."},{"question":"What is a load in structural engineering?","options":["A force or weight acting on a structure","Only a paint colour","The length of a website","The price of a ticket"],"correct_option_index":0,"explanation":"A load is something a structure must support."},{"question":"What does a lever help a person do?","options":["Create energy from nothing","Remove all friction","Make every object weightless","Change the effort or direction needed to move a load"],"correct_option_index":3,"explanation":"Levers provide mechanical advantage in suitable arrangements."},{"question":"Why is a safety factor used in design?","options":["To make every structure heavier without purpose","To guarantee that nothing can fail","To account for uncertainty and unexpected stresses","To avoid following building rules"],"correct_option_index":2,"explanation":"Safety factors allow margins beyond expected loads."},{"question":"What is friction?","options":["A battery''s colour","A force resisting relative motion between surfaces","A type of sunlight","The absence of gravity"],"correct_option_index":1,"explanation":"Friction acts against sliding or attempted sliding."},{"question":"Which material is commonly used for electrical insulation?","options":["Rubber","Copper","Silver","Aluminium"],"correct_option_index":0,"explanation":"Rubber generally resists electrical current."},{"question":"Why does a bicycle need brakes?","options":["To accelerate endlessly","To turn into an aircraft","To eliminate gravity","To slow and stop through controlled friction"],"correct_option_index":3,"explanation":"Brakes dissipate motion energy, often as heat."},{"question":"What is a renewable energy engineering challenge?","options":["Removing the need for wiring","Creating power from nothing","Storing electricity when the wind is not blowing","Making sunlight permanently disappear"],"correct_option_index":2,"explanation":"Energy storage helps balance variable renewable generation."},{"question":"A bridge prototype bends too far in a test. What should the team do?","options":["Assume the model is perfect","Review the load path and revise its design","Hide the test results","Increase the weight without analysis"],"correct_option_index":1,"explanation":"Tests should inform design changes."},{"question":"What is the role of a gear?","options":["Transmit rotation and change speed or torque","Store only sound","Produce light without electricity","Remove the need for bearings"],"correct_option_index":0,"explanation":"Gears transfer turning motion between shafts."},{"question":"What does an engineer mean by an iteration?","options":["A design that can never change","A laboratory chemical","A list of unrelated parts","A revised version after learning from a test"],"correct_option_index":3,"explanation":"Iteration improves a design through repeated cycles."},{"question":"Why must drinking-water systems be carefully designed?","options":["To remove all pressure","To use only glass everywhere","To deliver water safely and reduce contamination risk","To maximise colour in the pipes"],"correct_option_index":2,"explanation":"Public water systems need safe treatment and distribution."},{"question":"What is a sensor in a robot?","options":["A software advertisement","A device that measures conditions or detects changes","Only a wheel","The robot''s logo"],"correct_option_index":1,"explanation":"Sensors supply information to a control system."},{"question":"Why is accessibility important in building design?","options":["People with different mobility and sensory needs should be able to use spaces","Only one body size should be considered","Doors should always be narrow","Stairs can replace every entrance"],"correct_option_index":0,"explanation":"Inclusive design aims to remove barriers."},{"question":"What does a pulley system do?","options":["Turn water into fuel","Measure only temperature","Remove every load","Change the direction of a force and sometimes reduce effort"],"correct_option_index":3,"explanation":"Pulleys can offer mechanical advantage."},{"question":"Why do engineers record measurements during tests?","options":["To avoid using evidence","To hide incorrect results","To compare actual performance with requirements","To make documentation longer only"],"correct_option_index":2,"explanation":"Recorded data supports evidence-based decisions."},{"question":"What is a trade-off in design?","options":["Safety can always be ignored","Improving one feature may require sacrificing another","Every solution is perfect","Cost never matters"],"correct_option_index":1,"explanation":"Designs must balance several competing requirements."},{"question":"Which action shows good workshop safety?","options":["Wear suitable eye protection and follow tool instructions","Use damaged wires without checking","Touch moving gears deliberately","Leave sharp tools on the floor"],"correct_option_index":0,"explanation":"Protective equipment and safe procedures reduce risk."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000007","title":"World Cultures & Traditions","subject":"World Cultures","grade_level":"Year 6","language":"en","description":"20 cross-cultural questions on languages, traditions, food and respectful exchange.","questions":[{"question":"Why is it useful to learn greetings in another language?","options":["It guarantees perfect pronunciation","It replaces all listening skills","It can help show respect and start conversations","It makes every person speak English"],"correct_option_index":2,"explanation":"Trying another language can build connection and respect."},{"question":"What does cultural diversity mean?","options":["All communities celebrating identical holidays","Different cultural practices and experiences existing together","Everyone having exactly the same traditions","Only one language being allowed"],"correct_option_index":1,"explanation":"Diversity describes variation among communities."},{"question":"Which Malaysian festival is widely associated with decorative kolam designs?","options":["Deepavali","Christmas","Hari Gawai","Chap Goh Mei"],"correct_option_index":0,"explanation":"Kolam patterns are often displayed for Deepavali celebrations."},{"question":"What is a common element of Chinese New Year celebrations?","options":["A compulsory beach race","Only eating bread","Always celebrating in July","Family reunions and visits"],"correct_option_index":3,"explanation":"Reunion meals and visits are important for many families."},{"question":"Which celebration marks the end of Ramadan for Muslims?","options":["Vesak Day","Christmas","Hari Raya Aidilfitri","Deepavali"],"correct_option_index":2,"explanation":"Aidilfitri follows the Ramadan fasting month."},{"question":"What does the term ''heritage'' often include?","options":["A single type of uniform","Traditions, objects and knowledge passed between generations","Only newly invented apps","Items that nobody remembers"],"correct_option_index":1,"explanation":"Cultural heritage can be tangible or intangible."},{"question":"Why should visitors ask before photographing a cultural ceremony?","options":["Some people or activities require permission and respect","Cameras always take better photos at night","Tourists own every image","All ceremonies are public property"],"correct_option_index":0,"explanation":"Asking helps respect privacy and local customs."},{"question":"What is an oral tradition?","options":["Only written laws","A type of computer storage","A machine that makes fabric","Stories or knowledge shared through speaking"],"correct_option_index":3,"explanation":"Communities can pass knowledge verbally."},{"question":"Which instrument is associated with the Malaysian gamelan tradition?","options":["Tuba only","Electric guitar only","Gong","Bagpipe only"],"correct_option_index":2,"explanation":"Gamelan ensembles use instruments including gongs and metallophones."},{"question":"What does a traditional recipe often teach about a place?","options":["The length of all rivers","Local ingredients, history and customs","The exact weather next year","Every person''s favourite sport"],"correct_option_index":1,"explanation":"Food reflects resources, migration and community practices."},{"question":"Why is respectful disagreement important in intercultural discussions?","options":["People may have different beliefs and experiences","Every tradition must be identical","Disagreement is always unsafe","Listening has no value"],"correct_option_index":0,"explanation":"Respectful dialogue allows different perspectives."},{"question":"What is an example of intangible cultural heritage?","options":["A concrete bridge only","A single office printer","A plastic chair alone","A traditional dance performed across generations"],"correct_option_index":3,"explanation":"Performances and skills can be intangible heritage."},{"question":"What is a ''dialect'' in language?","options":["A type of musical key","A brand of keyboard","A regional or social variety of a language","A language that cannot be spoken"],"correct_option_index":2,"explanation":"Dialects vary in pronunciation, vocabulary or grammar."},{"question":"Which festival is celebrated in parts of Sabah by Kadazan-Dusun communities?","options":["Hanami","Kaamatan","Oktoberfest","Mardi Gras"],"correct_option_index":1,"explanation":"Kaamatan is associated with harvest celebrations in Sabah."},{"question":"What is a cultural stereotype?","options":["An oversimplified belief about a whole group","A reliable description of every individual","A recipe instruction","A verified historical date"],"correct_option_index":0,"explanation":"Stereotypes ignore differences between individuals."},{"question":"Why should museums describe where artefacts came from?","options":["Objects have no histories","Exhibits never need explanations","Labels always replace research","Provenance provides historical and ethical context"],"correct_option_index":3,"explanation":"Provenance helps explain origins and ownership."},{"question":"What does bilingual mean?","options":["Speaking without listening","Never learning a native language","Able to use two languages","Knowing only two words"],"correct_option_index":2,"explanation":"Bilingual people use two languages to varying degrees."},{"question":"What can music across cultures reveal?","options":["That songs contain no history","Different rhythms, instruments and social functions","That every song has the same beat","That culture never changes"],"correct_option_index":1,"explanation":"Music expresses creativity and community traditions."},{"question":"Which practice supports cultural exchange?","options":["Listening, asking respectful questions and sharing knowledge","Mocking unfamiliar customs","Assuming one culture is superior","Refusing translation help"],"correct_option_index":0,"explanation":"Exchange works better with curiosity and mutual respect."},{"question":"Why might a traditional craft be taught to younger people?","options":["To prevent all modern design","To stop people learning other crafts","To remove its cultural meaning","To preserve skills and allow creative adaptation"],"correct_option_index":3,"explanation":"Transmission can sustain heritage while allowing change."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000008","title":"Communities, Citizenship & Public Services","subject":"Civics","grade_level":"Year 7","language":"en","description":"20 non-partisan questions about communities, public services, shared rules and responsibility.","questions":[{"question":"What is the purpose of a public library?","options":["Replace every school","Provide access to books, information and learning resources","Sell only luxury goods","Keep all books private"],"correct_option_index":1,"explanation":"Libraries support education and community access."},{"question":"Why do communities have traffic rules?","options":["To reduce crashes and coordinate road use","To make journeys randomly longer","To prevent all walking","To ban every bicycle"],"correct_option_index":0,"explanation":"Shared rules improve predictability and safety."},{"question":"What does ''public service'' commonly refer to?","options":["Only a private birthday party","A personal game account","A fictional business name","Services intended to benefit the community"],"correct_option_index":3,"explanation":"Public services support shared needs."},{"question":"Why should school rules be clear and accessible?","options":["Only teachers need to know them","Clarity is not important","Students can understand expectations and apply them fairly","Rules should be secret"],"correct_option_index":2,"explanation":"Clear rules help people act consistently."},{"question":"What is volunteering?","options":["Secretly sharing passwords","Giving time or effort to help others without expecting wages","Borrowing money at high interest","Only buying products"],"correct_option_index":1,"explanation":"Volunteers support community activities."},{"question":"Why are emergency exits clearly marked?","options":["People need a route to safety during an emergency","To advertise nearby shops","To make corridors darker","To replace building maps for all uses"],"correct_option_index":0,"explanation":"Visible exit signs assist evacuation."},{"question":"What is a community consultation?","options":["A replacement for all laws","A private password exchange","A fixed school examination","An opportunity for residents to share views on a proposal"],"correct_option_index":3,"explanation":"Consultations collect perspectives on decisions."},{"question":"How should a disagreement about a shared playground be handled?","options":["Threaten other children","Ignore every concern","Discuss needs and seek a fair practical solution","Damage the playground"],"correct_option_index":2,"explanation":"Listening and compromise can resolve shared-space disputes."},{"question":"Why do towns collect household waste?","options":["To replace recycling with dumping everywhere","To maintain sanitation and manage materials safely","To increase litter","To block public roads"],"correct_option_index":1,"explanation":"Waste services reduce public health and environmental risks."},{"question":"What is a pedestrian crossing for?","options":["Helping people cross roads in a designated place","Marking a racing track","Parking vehicles permanently","Storing bicycles"],"correct_option_index":0,"explanation":"Crossings organise vehicle and pedestrian movement."},{"question":"Which practice shows responsible digital citizenship?","options":["Publish private messages for attention","Create false accounts to harass classmates","Spread unverified rumours","Respect others and avoid sharing private information without permission"],"correct_option_index":3,"explanation":"Good digital citizenship combines respect and privacy."},{"question":"Why are local parks important?","options":["They produce all drinking water","They replace every forest","They can offer recreation and support urban nature","They guarantee every city has identical weather"],"correct_option_index":2,"explanation":"Parks provide opportunities for play and green space."},{"question":"What does fairness in a classroom involve?","options":["Ignoring everyone with disabilities","Applying rules consistently while considering relevant needs","Giving prizes only to friends","Changing rules secretly"],"correct_option_index":1,"explanation":"Fair decisions need consistency and reasonable accommodation."},{"question":"What is a useful way to report a broken streetlight?","options":["Notify the appropriate local service with its location","Damage more lights","Post a classmate''s password","Invent an emergency"],"correct_option_index":0,"explanation":"Accurate reports help services identify the problem."},{"question":"What is a local community group?","options":["A single isolated machine","Only a national government","An online advertisement alone","People cooperating around a shared neighbourhood or interest"],"correct_option_index":3,"explanation":"Groups coordinate activities and mutual support."},{"question":"Why should public information be written clearly?","options":["Only experts use public facilities","Translation is never useful","Residents need to understand services and instructions","Confusing words improve safety"],"correct_option_index":2,"explanation":"Accessible language helps more people use information."},{"question":"What should someone do if they find a lost wallet at school?","options":["Hide it in a locker","Give it to a trusted staff member","Keep the cash","Publish identifying details online"],"correct_option_index":1,"explanation":"Staff can handle lost property safely."},{"question":"Why is listening important in group decisions?","options":["It helps reveal needs and concerns that others may have","It always guarantees agreement","It makes evidence irrelevant","It removes all rules"],"correct_option_index":0,"explanation":"Listening can lead to more informed decisions."},{"question":"What is a shared community resource?","options":["Only an individual password","A locked private diary","Someone else''s bank card","Something residents use or benefit from together"],"correct_option_index":3,"explanation":"Libraries, parks and pathways are examples of shared resources."},{"question":"Which action demonstrates care for public facilities?","options":["Leave taps running unnecessarily","Break safety signs","Use equipment responsibly and report damage","Carve names into school desks"],"correct_option_index":2,"explanation":"Responsible use helps facilities remain available to others."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000009","title":"Food, Cooking & Everyday Nutrition","subject":"Food & Nutrition","grade_level":"Year 6","language":"en","description":"20 questions on food safety, cooking skills, balanced meals and nutrition basics.","questions":[{"question":"Why should hands be washed before preparing food?","options":["To reduce the spread of microbes to food","To change the food''s flavour","To increase the water content of fruit","To make knives sharper"],"correct_option_index":0,"explanation":"Clean hands lower the chance of transferring harmful microbes."},{"question":"What is a balanced meal?","options":["Only sweets and drinks","The largest possible meal","A plate containing one food only","A meal including varied food groups in suitable proportions"],"correct_option_index":3,"explanation":"Variety helps provide different nutrients."},{"question":"Which nutrient is an important source of energy?","options":["Sand","Glass","Carbohydrates","Plastic"],"correct_option_index":2,"explanation":"Carbohydrates are one source of energy for the body."},{"question":"What is protein useful for?","options":["Making bones invisible","Growth and repair of body tissues","Replacing the need for water","Preventing all diseases"],"correct_option_index":1,"explanation":"Protein supplies amino acids used to build and repair tissues."},{"question":"What do dietary fibres help support?","options":["Normal digestion and bowel function","Instant muscle growth","Screen vision only","Replacing sleep"],"correct_option_index":0,"explanation":"Fibre supports digestive health."},{"question":"Why is clean drinking water important?","options":["It has no role in digestion","It replaces every food nutrient","It makes people never tired","It helps the body stay hydrated"],"correct_option_index":3,"explanation":"Water is essential for many normal body processes."},{"question":"Which method best lowers the risk of cross-contamination?","options":["Touch cooked food after handling raw meat without washing","Store raw chicken above fresh salad","Use separate tools or clean them between raw meat and ready-to-eat food","Use one dirty board for all ingredients"],"correct_option_index":2,"explanation":"Separation and cleaning reduce transfer of harmful microorganisms."},{"question":"Why should raw poultry be cooked thoroughly?","options":["To make storage unnecessary","To reduce foodborne infection risk","To make it weigh exactly twice as much","To remove all vitamins"],"correct_option_index":1,"explanation":"Adequate cooking destroys many dangerous microorganisms."},{"question":"Why should foods be stored at appropriate temperatures?","options":["To slow harmful microbial growth and spoilage","To change every food into ice","To remove the need to wash produce","To make expiry dates irrelevant"],"correct_option_index":0,"explanation":"Temperature control is a key part of food safety."},{"question":"What does a food ingredient list show?","options":["The name of every customer","Only the company''s advertising slogan","The future weather forecast","Ingredients used to make a packaged product"],"correct_option_index":3,"explanation":"Ingredient lists help consumers understand what is in a product."},{"question":"Which is a healthy approach to eating?","options":["Eat the same snack for every meal","Avoid drinking water","Choose varied foods and listen to hunger and fullness cues","Skip all meals to study longer"],"correct_option_index":2,"explanation":"Balanced eating and routine habits support health."},{"question":"Why can home cooking be a useful skill?","options":["It replaces safe knife practices","It helps people plan ingredients, hygiene and portion choices","It guarantees all meals are perfect","It eliminates all grocery costs"],"correct_option_index":1,"explanation":"Cooking skills support informed food preparation."},{"question":"What are legumes?","options":["Plants such as beans, peas and lentils","Only kinds of fish","Types of kitchen knives","A form of bottled water"],"correct_option_index":0,"explanation":"Legumes are edible seeds from plants in the legume family."},{"question":"Which food group commonly provides calcium?","options":["Cooking oil alone","White sugar alone","Plain table salt","Milk, yoghurt or fortified alternatives"],"correct_option_index":3,"explanation":"Dairy and some fortified alternatives can contribute calcium."},{"question":"What is a recipe''s ingredient quantity for?","options":["Showing only cooking temperature","Advertising the kitchen","Measuring what is needed to prepare a dish","Determining the cook''s age"],"correct_option_index":2,"explanation":"Correct quantities improve consistency and reduce waste."},{"question":"A recipe serves four people. For eight people, what should you usually do to ingredient amounts?","options":["Keep every ingredient unchanged","Double the ingredients","Halve the ingredients","Use no ingredients"],"correct_option_index":1,"explanation":"Doubling servings generally doubles ingredient quantities."},{"question":"Why should vegetables be washed before eating?","options":["To remove some dirt and surface contamination","To turn them into fruit","To eliminate the need for safe storage","To add protein to every vegetable"],"correct_option_index":0,"explanation":"Washing can remove soil and some contaminants."},{"question":"What is food waste?","options":["Only empty packaging","Every compost pile","Only food in restaurants","Food intended for consumption that is discarded"],"correct_option_index":3,"explanation":"Wasted food uses resources without being eaten."},{"question":"Which method helps reduce food waste at home?","options":["Discard food before checking it","Ignore storage instructions","Plan portions and safely use leftovers","Buy more than you can store"],"correct_option_index":2,"explanation":"Planning and proper storage reduce unnecessary waste."},{"question":"Why is the nutrition information panel useful?","options":["It tells you who bought the food","It helps compare energy and nutrient amounts across foods","It proves every product is healthy","It replaces medical advice"],"correct_option_index":1,"explanation":"Nutrition panels provide standardised information for comparison."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000010","title":"Weather Watchers & Climate Patterns","subject":"Weather","grade_level":"Year 6","language":"en","description":"20 questions on clouds, rainfall, forecasts and safe weather awareness.","questions":[{"question":"What instrument measures rainfall amount?","options":["Compass","Stopwatch","Balance scale","Rain gauge"],"correct_option_index":3,"explanation":"A rain gauge collects rainfall to measure its depth."},{"question":"What is air pressure?","options":["The number of clouds only","The size of a mountain","The force of air acting over an area","The colour of a rainbow"],"correct_option_index":2,"explanation":"Air has mass and exerts pressure."},{"question":"What does an anemometer measure?","options":["Water depth","Wind speed","Soil acidity","Earthquake magnitude"],"correct_option_index":1,"explanation":"Anemometers are used to measure wind speed."},{"question":"How do many clouds form?","options":["Water vapour cools and condenses into droplets or ice crystals","The ocean turns into smoke","Mountains release cotton","Sunlight becomes sand"],"correct_option_index":0,"explanation":"Condensation produces droplets and crystals suspended in air."},{"question":"What is humidity?","options":["The number of birds in a tree","The strength of a compass","The colour of soil","The amount of water vapour in the air"],"correct_option_index":3,"explanation":"Humidity describes atmospheric water vapour."},{"question":"What is the main difference between weather and climate?","options":["They are identical terms","Climate describes only today''s rain","Weather is short-term conditions; climate is long-term patterns","Weather lasts centuries; climate lasts one minute"],"correct_option_index":2,"explanation":"Climate is described using longer-term statistics of weather."},{"question":"What causes a rainbow?","options":["Only lightning","Sunlight refracting, reflecting and dispersing in water droplets","Clouds producing coloured paint","Air becoming solid"],"correct_option_index":1,"explanation":"Light interacts with droplets to create a spectrum."},{"question":"What is a thunderstorm?","options":["A storm with lightning and thunder","Any quiet sunny day","A type of ocean current","An eclipse of the Moon"],"correct_option_index":0,"explanation":"Electrical activity in storm clouds causes lightning."},{"question":"During nearby lightning, what is the safest general place to be?","options":["Under a lone tall tree","On an open sports field","Swimming in a lake","Inside a substantial building"],"correct_option_index":3,"explanation":"Indoor shelter is safer during lightning."},{"question":"Why can steep slopes be dangerous after heavy rain?","options":["Gravity stops acting","The soil becomes weightless","Water may destabilise soil and contribute to landslides","Rain always makes mountains taller"],"correct_option_index":2,"explanation":"Saturated ground can increase slope failure risk."},{"question":"What does a weather forecast estimate?","options":["Which song will be popular tomorrow","Likely atmospheric conditions over a period","Exact weather with perfect certainty","The age of every tree"],"correct_option_index":1,"explanation":"Forecasts use observations and models to estimate future conditions."},{"question":"Which measurement describes temperature?","options":["Degrees Celsius","Kilograms per second","Metres per litre","Newtons per minute"],"correct_option_index":0,"explanation":"Temperature is commonly measured in Celsius."},{"question":"What is the monsoon?","options":["A type of insect","A daily ocean tide","A bright star","A seasonal pattern of winds associated with rainfall changes"],"correct_option_index":3,"explanation":"Monsoon circulations influence seasonal rainfall in many regions."},{"question":"Why do meteorologists use weather satellites?","options":["To create sunlight","To replace all ground measurements","To observe cloud patterns and atmospheric features","To directly change every storm"],"correct_option_index":2,"explanation":"Satellite data supplements surface observations."},{"question":"Why are storm drains important in cities?","options":["They turn rivers into roads","They carry away excess surface water when functioning properly","They make rainfall stop","They increase every flood risk automatically"],"correct_option_index":1,"explanation":"Drainage systems manage runoff, within design limits."},{"question":"What is evaporation in the water cycle?","options":["Liquid water becoming vapour","Clouds freezing into rock","Rain becoming electricity","Wind turning into water"],"correct_option_index":0,"explanation":"Evaporation moves water from surfaces into the air."},{"question":"What is a drought?","options":["One short rain shower","A period of excess flooding everywhere","Any day with clouds","A prolonged period of unusually low water availability"],"correct_option_index":3,"explanation":"Drought reflects extended water shortages."},{"question":"Why are heat warnings useful?","options":["They replace drinking water","They guarantee cool weather","They help people plan hydration, shade and reduced heat exposure","They prevent every hot day"],"correct_option_index":2,"explanation":"Heat advisories communicate elevated heat risk."},{"question":"What makes a sea breeze more likely during daytime near the coast?","options":["All winds suddenly disappearing","Land heating more quickly than nearby sea water","The sea completely stopping waves","The Moon becoming brighter"],"correct_option_index":1,"explanation":"Uneven heating can create local air circulation."},{"question":"Why should a school have a weather emergency plan?","options":["To guide safe shelter, communications and activities","To ensure there will never be storms","To stop teachers using maps","To replace normal lessons permanently"],"correct_option_index":0,"explanation":"Prepared procedures help people respond effectively."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000011","title":"Wildlife, Habitats & Biodiversity","subject":"Animals & Nature","grade_level":"Year 6","language":"en","description":"20 questions about animal adaptations, habitats, conservation and ecosystems.","questions":[{"question":"In conservation science, what does biodiversity describe?","options":["Only one tree species","A type of electrical circuit","The variety of living organisms and ecological systems","The number of buildings in a city"],"correct_option_index":2,"explanation":"Biodiversity includes species, genetic and ecosystem diversity."},{"question":"In wildlife ecology, what does the term habitat mean?","options":["A laboratory temperature scale","The natural place where an organism lives","Only a type of zoo ticket","A single television programme"],"correct_option_index":1,"explanation":"Habitats provide resources and conditions for organisms."},{"question":"Why do birds have different beak shapes?","options":["They are adapted for different foods and ways of feeding","All birds eat the same seeds","Beaks never change across species","Beaks measure rainfall"],"correct_option_index":0,"explanation":"Beak form is linked to diet and ecological role."},{"question":"What is camouflage?","options":["A type of artificial intelligence model","A form of musical notation","A replacement for breathing","Features that help an organism blend with surroundings"],"correct_option_index":3,"explanation":"Camouflage can make animals harder to detect."},{"question":"What is a nocturnal animal?","options":["A plant that floats","A fish that never swims","An animal active mainly at night","An animal with no bones"],"correct_option_index":2,"explanation":"Nocturnal species are primarily active after dark."},{"question":"What is migration in animals?","options":["A kind of photosynthesis","Seasonal movement between regions","Changing a computer password","Every movement within one cage"],"correct_option_index":1,"explanation":"Migration can follow seasonal food and breeding opportunities."},{"question":"Which animal is an amphibian?","options":["Frog","Eagle","Butterfly","Earthworm"],"correct_option_index":0,"explanation":"Frogs are amphibians with life stages linked to water and land."},{"question":"What is an invertebrate?","options":["An animal with feathers only","A plant with roots","A large mammal only","An animal without a backbone"],"correct_option_index":3,"explanation":"Invertebrates include insects, molluscs and many other groups."},{"question":"Why are wetlands valuable?","options":["They prevent every drought","They are always dry","They provide habitat, filter some pollutants and store water","They contain no living organisms"],"correct_option_index":2,"explanation":"Wetlands support biodiversity and water regulation."},{"question":"What can happen if an important pollinator declines?","options":["No flowering plant can reproduce at all","Some plants may produce fewer fruits or seeds","All crops instantly stop growing","Every fish disappears"],"correct_option_index":1,"explanation":"Many plants benefit from animal pollination."},{"question":"What is an endangered species?","options":["A species facing a high risk of extinction","A species that is always common","Any pet that is sleepy","A newly planted flower"],"correct_option_index":0,"explanation":"Endangered classifications reflect elevated extinction risk."},{"question":"What does a conservation programme try to do?","options":["Replace every wild animal with a robot","Remove all native plants","Make all forests identical","Protect species, habitats or natural resources"],"correct_option_index":3,"explanation":"Conservation aims to sustain ecosystems and species."},{"question":"Why should wild animals not be fed unfamiliar human foods?","options":["It guarantees more biodiversity","All human food is suitable for wildlife","It may harm their health and natural behaviour","It always makes them immortal"],"correct_option_index":2,"explanation":"Feeding wildlife can introduce poor diets and dependence."},{"question":"What is a keystone species?","options":["Any tree older than ten years","A species whose influence on its ecosystem is unusually large","Only the largest animal in a zoo","An organism living only in caves"],"correct_option_index":1,"explanation":"Some species strongly shape ecosystem interactions."},{"question":"Why are connected wildlife corridors useful?","options":["They help animals move between fragmented habitats","They block every migration route","They create new oceans","They replace all protected forests"],"correct_option_index":0,"explanation":"Corridors can maintain movement and genetic exchange."},{"question":"When studying an ecosystem, what does a food chain show?","options":["A metal chain used in farming","A plan for cooking lessons","A list of weather stations","A simple sequence showing who eats whom"],"correct_option_index":3,"explanation":"Food chains represent the transfer of energy through feeding."},{"question":"What is an invasive species?","options":["A species found in its original home","A plant that always produces flowers","A non-native organism that spreads and causes ecological harm","Any animal in a nature reserve"],"correct_option_index":2,"explanation":"Some introduced species can damage native ecosystems."},{"question":"Why do some animals have thick fur in cold environments?","options":["It generates all sunlight","It can help reduce heat loss","It makes them weightless","It prevents the need for food"],"correct_option_index":1,"explanation":"Insulating fur helps maintain body temperature."},{"question":"What is an example of symbiosis?","options":["Two different species living in close ecological association","A thunderstorm moving across a city","A robot charging a battery","A single rock breaking apart"],"correct_option_index":0,"explanation":"Symbiosis refers to close interactions between distinct species."},{"question":"Which activity helps protect local wildlife?","options":["Collect every wild egg","Release unwanted pets into forests","Leave fishing lines in rivers","Respect habitats and avoid disturbing nests"],"correct_option_index":3,"explanation":"Reducing disturbance protects animals and habitat."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000012","title":"Critical Thinking & Smart Decisions","subject":"Critical Thinking","grade_level":"Year 7","language":"en","description":"20 scenarios about reasoning, evaluating evidence, probability and thoughtful choices.","questions":[{"question":"A friend says ''everyone likes this game''. What should you ask?","options":["Can the game have more colours?","What evidence supports ''everyone''?","How loud can the claim be repeated?","Who has the biggest phone?"],"correct_option_index":1,"explanation":"Broad claims need evidence about the relevant group."},{"question":"What is a logical conclusion?","options":["A claim that follows from evidence and reasoning","A random guess stated confidently","Any rumour with a picture","A sentence with many emojis"],"correct_option_index":0,"explanation":"Sound conclusions are supported by relevant reasons."},{"question":"A study shows two events happen together. What does that prove by itself?","options":["One must cause the other","Both are always accidental","The study is automatically false","They are associated, not necessarily that one causes the other"],"correct_option_index":3,"explanation":"Correlation alone does not establish causation."},{"question":"Which is the best question when solving a problem?","options":["Can we skip collecting information?","How can we make the problem sound bigger?","What exactly is the problem we need to solve?","Who should we blame first?"],"correct_option_index":2,"explanation":"Clear problem definitions guide solutions."},{"question":"You hear two conflicting claims. What is a good next step?","options":["Share both as certain facts","Check evidence and the reliability of each source","Choose the louder speaker","Accept whichever seems more exciting"],"correct_option_index":1,"explanation":"Evidence quality matters more than confidence."},{"question":"Which is an example of a testable prediction?","options":["If plants receive less water, their growth may change","This plant is the prettiest ever","Everyone must enjoy gardening","The colour green is always best"],"correct_option_index":0,"explanation":"A prediction is testable when observations can support or challenge it."},{"question":"What is an assumption?","options":["A measured temperature","A verified receipt","A recorded observation only","An idea accepted without being directly established in the argument"],"correct_option_index":3,"explanation":"Assumptions can influence reasoning and should be examined."},{"question":"Why is it useful to consider an alternative explanation?","options":["It removes the need for testing","It makes all explanations identical","It can reveal whether the first explanation is sufficient","It guarantees the first idea is wrong"],"correct_option_index":2,"explanation":"Competing hypotheses help test reasoning."},{"question":"A claim uses only one success story to promise results for everyone. What is the weakness?","options":["No examples can be useful","One example may not represent a wider group","All personal stories are false","Success is impossible to measure"],"correct_option_index":1,"explanation":"Anecdotes do not establish general outcomes."},{"question":"What is a fair comparison in an experiment?","options":["Change one main variable while controlling other relevant conditions","Change every variable at once","Hide the control group","Report only favourite results"],"correct_option_index":0,"explanation":"Controlling conditions helps isolate effects."},{"question":"Why use a checklist for a complex task?","options":["It automatically completes the task","It removes all uncertainty","It guarantees no item will ever change","It helps avoid forgetting important steps"],"correct_option_index":3,"explanation":"Checklists support consistency and memory."},{"question":"A shop offers ''buy two, get one free''. What should you check?","options":["The background music","The number of stars in the logo","Whether you need three items and the total cost","Only the word ''free''"],"correct_option_index":2,"explanation":"An offer is useful only if it fits real needs and budget."},{"question":"What is a decision criterion?","options":["An unrelated slogan","A standard used to compare possible choices","A random preference not recorded","A secret password"],"correct_option_index":1,"explanation":"Criteria clarify what matters for a choice."},{"question":"Why do scientists report limitations of a study?","options":["To explain uncertainty and where results may not apply","To invalidate every result automatically","To avoid peer review","To make the title longer"],"correct_option_index":0,"explanation":"Limitations help readers interpret results appropriately."},{"question":"What is an example of circular reasoning?","options":["The measured length is 5 cm","The receipt lists three items","The plant grew 2 cm","This claim is true because it is correct"],"correct_option_index":3,"explanation":"Circular reasoning assumes what it claims to prove."},{"question":"What is a counterexample?","options":["A type of questionnaire","A random nickname","An instance that challenges a general claim","An example supporting every rule"],"correct_option_index":2,"explanation":"One valid counterexample can disprove a universal statement."},{"question":"A forecast says a 30% chance of rain. What does it communicate?","options":["There is no uncertainty","Rain is possible but not certain in the forecast conditions","Rain must happen for 30 minutes","Rain will cover exactly 30% of each road"],"correct_option_index":1,"explanation":"Probability estimates likelihood, not guaranteed outcomes."},{"question":"Why should a group identify constraints before designing a solution?","options":["Time, budget and safety limits affect what is feasible","Constraints never affect choices","Planning can ignore materials","Every idea costs the same"],"correct_option_index":0,"explanation":"Constraints shape realistic options."},{"question":"When an unexpected result appears, what is a responsible response?","options":["Delete it without explanation","Change the data to match your theory","Assume all instruments are broken","Check measurements and investigate possible causes"],"correct_option_index":3,"explanation":"Unexpected evidence deserves careful analysis."},{"question":"Which approach helps a team make a balanced decision?","options":["Ignore future effects","Count only positive comments","Compare benefits, risks and evidence before choosing","Ask only one person to decide secretly"],"correct_option_index":2,"explanation":"Balanced decisions consider multiple relevant factors."}]}]'::jsonb AS packs)
INSERT INTO public.quiz_sets(id,title,subject,grade_level,language,description,status)
SELECT (p.value->>'id')::uuid,p.value->>'title',p.value->>'subject',p.value->>'grade_level',p.value->>'language',p.value->>'description','published'
FROM bundle CROSS JOIN LATERAL jsonb_array_elements(bundle.packs) AS p(value)
ON CONFLICT (id) DO NOTHING;
WITH bundle AS (SELECT '[{"id":"c8202611-05b0-4a9b-9f00-000000000001","title":"生活理财：从零花钱到预算","subject":"生活理财","grade_level":"Year 6","language":"zh","description":"20 道原创生活理财题，学习预算、储蓄、消费者权益与消费判断。","questions":[{"question":"小明每周有 RM20 零花钱，花 RM12 后还剩多少？","options":["RM8","RM6","RM10","RM12"],"correct_option_index":0,"explanation":"RM20 减去 RM12，剩下 RM8。"},{"question":"“预算”最主要的用途是什么？","options":["保证每次购物打折","让钱自动增加","避免记录花费","提前规划收入与支出"],"correct_option_index":3,"explanation":"预算帮助安排有限资金的用途。"},{"question":"你有 RM50，想买 RM35 的书和 RM20 的玩具，最合理的做法是？","options":["向陌生人借钱","不看价格直接付款","先按需要选择并核算总价","两件都买不用计算"],"correct_option_index":2,"explanation":"两件共 RM55，超出预算 RM5。"},{"question":"哪一种行为属于“储蓄”？","options":["不记得钱放在哪里","把部分零花钱留作日后使用","把全部钱当天花完","借钱买不需要的东西"],"correct_option_index":1,"explanation":"储蓄是把当前资源保留给未来。"},{"question":"“需要”和“想要”有什么区别？","options":["需要是基本必要，想要是额外愿望","两者完全一样","想要永远更重要","需要只指玩具"],"correct_option_index":0,"explanation":"区分必要支出和可选消费能改善预算。"},{"question":"商品标价 RM24，折扣 RM4，实付多少？","options":["RM28","RM22","RM16","RM20"],"correct_option_index":3,"explanation":"实付价格为原价减优惠额。"},{"question":"两家商店同款笔分别卖 RM3 和 RM5，哪家更便宜？","options":["两家一样","不能比较","RM3 的商店","RM5 的商店"],"correct_option_index":2,"explanation":"在质量和条件相同时，RM3 比 RM5 便宜。"},{"question":"“收据”一般可以帮助你做什么？","options":["让商品永远不损坏","核对付款记录与购买凭证","自动增加银行余额","代替所有身份证明"],"correct_option_index":1,"explanation":"收据是交易记录，退换货时也可能有用。"},{"question":"看到“限时五分钟立刻付款”的广告，你应该先怎样做？","options":["比较价格并确认是否真的需要","立即付款不考虑","把密码交给卖家","相信所有倒计时"],"correct_option_index":0,"explanation":"倒计时可能制造冲动消费压力。"},{"question":"什么是“利息”？","options":["商品包装颜色","一张购物清单","固定不变的折扣","借贷或存款可能涉及的资金使用成本或回报"],"correct_option_index":3,"explanation":"利息通常按本金、利率和时间计算。"},{"question":"想存 RM60，每周存 RM10，大约需要几周？","options":["7 周","10 周","6 周","5 周"],"correct_option_index":2,"explanation":"RM60 ÷ RM10 = 6 周。"},{"question":"为什么不应随意分享银行卡密码？","options":["有助于获得免费礼物","可能让别人未经许可使用账户","会让银行卡变轻","能增加存款利息"],"correct_option_index":1,"explanation":"银行卡密码属于敏感的金融验证信息。"},{"question":"现金付款和电子付款有什么共同点？","options":["都应该核对实际支付金额","都不需要保护隐私","都不会发生错误","都可以无限支付"],"correct_option_index":0,"explanation":"无论支付方式，都需要确认金额与收款对象。"},{"question":"如果商品出现质量问题，最实用的第一步是什么？","options":["立即公开所有个人资料","丢弃所有收据","随意转账给陌生客服","保存凭证并联系合法销售渠道"],"correct_option_index":3,"explanation":"保留证据有助于与商家沟通。"},{"question":"“单价”可以帮助你比较什么？","options":["商店音乐好不好听","广告字体大小","不同包装的单位成本","商品颜色是否好看"],"correct_option_index":2,"explanation":"单位价格可以比较每克或每件的成本。"},{"question":"同样的饮料，250 mL 售 RM2，500 mL 售 RM3，哪个每毫升更划算？","options":["无法判断","500 mL 售 RM3","250 mL 售 RM2","两者单位价格一样"],"correct_option_index":1,"explanation":"每毫升分别为 RM0.008 和 RM0.006。"},{"question":"什么是“紧急备用金”？","options":["留给意外必要支出的储蓄","专门买玩具的钱","每天必须花完的钱","任何人的共享密码"],"correct_option_index":0,"explanation":"备用金可以帮助应付突发的合理开支。"},{"question":"购买数字游戏道具前，为什么要先确认费用？","options":["数字商品永远免费","所有付费道具都能退款","付款不需要监护人知道","虚拟购买也可能产生真实支出"],"correct_option_index":3,"explanation":"游戏内购买也会消耗真实资金。"},{"question":"朋友向你推荐“稳赚不赔”的投资，哪种判断更审慎？","options":["公开账户密码","邀请同学一起冲动投资","怀疑保证回报的说法并向可信成年人求证","马上投入全部存款"],"correct_option_index":2,"explanation":"任何投资都有风险，保证高回报的说法值得警惕。"},{"question":"每月记录自己的花费，最大的价值是什么？","options":["确保未来没有意外","发现消费习惯并改进安排","让价格自动下降","避免学习数学"],"correct_option_index":1,"explanation":"记录支出能帮助识别不必要的花费。"}]},{"id":"c8202611-05b0-4a9b-9f00-000000000002","title":"Young Entrepreneurs: Ideas & Customers","subject":"Entrepreneurship","grade_level":"Year 7","language":"en","description":"20 realistic questions about business ideas, customer needs, feedback and simple costs.","questions":[{"question":"What is a business customer?","options":["Only the shop owner","A machine in a factory","An online password","Someone who buys or uses a product or service"],"correct_option_index":3,"explanation":"Customers are people or organisations served by a business."},{"question":"A team wants to sell reusable bottles. What should it learn first?","options":["How to skip safety rules","How to copy every rival logo","Whether customers need and want the bottles","The colour of the founder''s shoes"],"correct_option_index":2,"explanation":"Understanding customer needs helps define a useful product."},{"question":"What does a prototype help a team do?","options":["Remove every design risk","Test an early version of an idea","Guarantee a billion sales","Avoid customer feedback"],"correct_option_index":1,"explanation":"A prototype lets people try and evaluate a concept."},{"question":"What is revenue?","options":["Money received from selling goods or services","Only the money left after expenses","The number of shop chairs","A company''s logo colours"],"correct_option_index":0,"explanation":"Revenue is sales income before subtracting expenses."},{"question":"What is a cost to a small bakery?","options":["A customer compliment","A social media follower","A product review","Ingredients used to make bread"],"correct_option_index":3,"explanation":"Ingredients are resources the bakery pays for."},{"question":"A school stall sells ten bookmarks for RM3 each. What is total sales revenue?","options":["RM7","RM33","RM30","RM13"],"correct_option_index":2,"explanation":"Ten multiplied by RM3 equals RM30 in revenue."},{"question":"If revenue is RM30 and total expenses are RM18, what is the simple profit?","options":["RM30","RM12","RM48","RM18"],"correct_option_index":1,"explanation":"Profit is revenue minus expenses, here RM12."},{"question":"Why should a startup ask users for feedback?","options":["To learn what actually works and what needs improvement","To prove its first idea is always perfect","To collect unnecessary passwords","To avoid future changes"],"correct_option_index":0,"explanation":"User feedback helps identify problems and improvements."},{"question":"What is a value proposition?","options":["An automatic bank transfer","A list of all employee birthdays","A random slogan without meaning","A clear explanation of how a product helps customers"],"correct_option_index":3,"explanation":"A value proposition states the benefit a customer can expect."},{"question":"Which is an ethical way to promote a product?","options":["Hide important charges","Claim untested medical benefits","Describe its real features accurately","Invent positive reviews"],"correct_option_index":2,"explanation":"Accurate claims support customer trust."},{"question":"A competitor offers a similar product. What should a founder do?","options":["Copy their private customer list","Understand differences and improve their own offer","Steal their accounts","Publish false rumours"],"correct_option_index":1,"explanation":"Fair competition focuses on genuine customer value."},{"question":"What does a break-even point describe?","options":["The level where revenue covers costs","A moment when no product can be sold","A fixed discount of 50 percent","When a shop closes every day"],"correct_option_index":0,"explanation":"At break-even, total revenue equals total costs."},{"question":"Why does accessibility matter for a student app?","options":["It always increases the price","It prevents all bugs","It replaces customer support","More people can use it despite different abilities"],"correct_option_index":3,"explanation":"Accessible design reduces unnecessary barriers."},{"question":"What is a recurring customer?","options":["A supplier of electricity","An imaginary user","A customer who returns to buy or use a service again","A person visiting once"],"correct_option_index":2,"explanation":"Returning users can indicate continuing usefulness."},{"question":"What should a team do with a failed prototype?","options":["Ignore the evidence","Identify the cause and revise the design","Pretend the test never happened","Immediately blame users"],"correct_option_index":1,"explanation":"Failure information supports iteration."},{"question":"What is a partnership in a project?","options":["Two parties cooperating toward agreed goals","One person secretly using another''s brand","A promise of guaranteed profit","An automatic legal registration"],"correct_option_index":0,"explanation":"A partnership is cooperation based on an agreed purpose."},{"question":"Why track simple business metrics?","options":["To make graphs look impressive only","To replace product quality","To avoid talking to customers","To observe progress against a goal"],"correct_option_index":3,"explanation":"Useful metrics help identify changes over time."},{"question":"A customer reports a real problem. Which response is best?","options":["Mock the customer publicly","Invent a technical excuse","Listen, investigate and communicate a resolution","Delete the message without reading"],"correct_option_index":2,"explanation":"Respectful support and investigation can resolve issues."},{"question":"Why should product prices be transparent?","options":["Only the seller should know the cost","Customers need to understand what they will pay","Hidden charges build trust","Prices have no effect on decisions"],"correct_option_index":1,"explanation":"Clear pricing supports informed choices."},{"question":"A business idea collects students'' personal data. What should the team prioritize?","options":["Collect only necessary data and protect it","Publish every student''s address","Sell private data without permission","Use the same password for all staff"],"correct_option_index":0,"explanation":"Privacy should be built into the product from the beginning."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000003","title":"Media Detectives: Facts & Misinformation","subject":"Media Literacy","grade_level":"Year 7","language":"en","description":"20 media literacy scenarios about sources, misleading posts, social networks and verification.","questions":[{"question":"A viral post has no named source. What is a sensible first step?","options":["Assume popularity proves truth","Edit it to sound more dramatic","Find an independent trustworthy source","Forward it immediately"],"correct_option_index":2,"explanation":"Popularity is not evidence that a claim is correct."},{"question":"What is a primary source for a speech?","options":["An advertisement for the event","A recording or transcript of the original speech","A stranger''s summary","An unrelated opinion article"],"correct_option_index":1,"explanation":"Primary sources provide direct evidence."},{"question":"What is a headline''s main purpose?","options":["Introduce the subject and attract a reader","Replace the entire article","Guarantee every statement is true","Identify every source automatically"],"correct_option_index":0,"explanation":"A headline summarises or promotes content but cannot replace verification."},{"question":"A photo from 2019 is shared as today''s flood. What is the problem?","options":["Older photos cannot be useful","Photos never show real events","All floods are identical","The image is presented with misleading timing"],"correct_option_index":3,"explanation":"An authentic image can mislead when placed in false context."},{"question":"How can you check whether a photograph is reused elsewhere?","options":["Ask the poster to use more emojis","Assume its caption is accurate","Search for earlier appearances of the image","Count its pixels only"],"correct_option_index":2,"explanation":"Earlier appearances may reveal the photo''s original context."},{"question":"What is an opinion?","options":["An official receipt","A personal judgement that may differ between people","A measurement guaranteed to be exact","A statement always false"],"correct_option_index":1,"explanation":"Opinions express preferences or judgements."},{"question":"Which statement is directly verifiable?","options":["The event begins at 9:00 AM on Saturday","This is the best event ever","The music is wonderful","That poster looks ugly"],"correct_option_index":0,"explanation":"A published schedule can verify a stated starting time."},{"question":"A sponsored post promotes a product. What should viewers recognise?","options":["Advertising makes every claim true","Sponsored content is always illegal","No sponsorship disclosure is ever needed","The creator may have a commercial incentive"],"correct_option_index":3,"explanation":"Sponsorship can affect the motivation behind a message."},{"question":"What is confirmation bias?","options":["Measuring weather accurately","Reading multiple viewpoints fairly","Preferring information that supports existing beliefs","Changing the topic of a report"],"correct_option_index":2,"explanation":"People may selectively notice evidence supporting their views."},{"question":"Why compare reports from multiple independent sources?","options":["It replaces direct observation in every case","It can reveal mistakes and missing context","It guarantees everyone agrees","It removes the need for evidence"],"correct_option_index":1,"explanation":"Independent reporting can improve confidence."},{"question":"What is a deepfake?","options":["Synthetic media made to imitate a real person or event","A very old newspaper","A type of safe backup","A computer cooling system"],"correct_option_index":0,"explanation":"AI-generated video or audio can simulate appearances or voices."},{"question":"A convincing AI voice note asks for money. What is safest?","options":["Pay immediately","Share your banking PIN","Assume the voice cannot be forged","Verify identity through a separate trusted channel"],"correct_option_index":3,"explanation":"Voice recordings can be imitated, so verification matters."},{"question":"What does a citation help readers do?","options":["Hide the original author","Replace all critical thinking","Locate the evidence supporting a claim","Make an article automatically correct"],"correct_option_index":2,"explanation":"Citations let others inspect the source material."},{"question":"Why can a cropped chart be misleading?","options":["Only the colours matter","It may hide important axis values or comparison context","Cropping always improves accuracy","Charts never use numbers"],"correct_option_index":1,"explanation":"Missing scales can exaggerate or minimise differences."},{"question":"An online claim cites ''experts'' but no names or studies. What is missing?","options":["Identifiable evidence that can be checked","An exciting background song","A larger font","More reaction emojis"],"correct_option_index":0,"explanation":"Unspecified authorities are difficult to verify."},{"question":"Which question is useful when reading a news article?","options":["How many colourful icons appear?","Can it make me angry quickly?","Does it have many capital letters?","Who produced it and what evidence supports it?"],"correct_option_index":3,"explanation":"Assessing source and evidence helps evaluate accuracy."},{"question":"What is clickbait?","options":["A verified scientific reference","A school attendance register","A sensational heading designed to attract clicks","Any careful investigative report"],"correct_option_index":2,"explanation":"Clickbait often prioritises clicks over clear context."},{"question":"Which is a responsible way to correct a mistaken post?","options":["Invent a new rumour","Explain the correction and provide reliable evidence","Insult anyone who believed it","Delete every opposing opinion"],"correct_option_index":1,"explanation":"Evidence-based corrections help others update beliefs."},{"question":"Why distinguish a simulation from real footage?","options":["Viewers deserve to know what actually happened","All visual media must be forbidden","Simulations are always useless","Reality can be determined by video quality alone"],"correct_option_index":0,"explanation":"Labels prevent fictional reconstructions from being mistaken for records."},{"question":"A study cited online has only ten participants. What should you consider?","options":["That the conclusion must be universal","That statistics can be ignored","That every small study is fraudulent","Whether the sample size and design support the claim"],"correct_option_index":3,"explanation":"Study design and sample size affect how findings can be interpreted."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000004","title":"Farms, Food Systems & Agriculture","subject":"Agriculture","grade_level":"Year 6","language":"en","description":"20 questions on crops, soil, sustainable farming, pollination and food supply chains.","questions":[{"question":"Why do farmers rotate different crops across seasons?","options":["To avoid harvesting food","To help maintain soil health and manage pests","To make every plant look identical","To prevent all rainfall"],"correct_option_index":1,"explanation":"Crop rotation can reduce some pests and improve nutrient balance."},{"question":"Which plant part usually develops into a fruit after fertilisation?","options":["The flower''s ovary","The root tip","The bark","The stem hair"],"correct_option_index":0,"explanation":"In flowering plants, the ovary commonly develops into a fruit."},{"question":"What is compost?","options":["A type of plastic fertiliser bottle","Only pure sand","An insecticide spray","Decomposed organic material used to enrich soil"],"correct_option_index":3,"explanation":"Compost returns organic matter and nutrients to soil."},{"question":"Why are bees important to many crops?","options":["They replace soil nutrients","They make every plant grow instantly","They move pollen between flowers","They create all rainfall"],"correct_option_index":2,"explanation":"Pollinators enable fertilisation for many flowering plants."},{"question":"Which practice helps conserve irrigation water?","options":["Removing all soil cover","Drip irrigation near plant roots","Leaving hoses running all day","Watering paved roads"],"correct_option_index":1,"explanation":"Drip systems can deliver water efficiently to roots."},{"question":"What does a seed need to germinate in most common crops?","options":["Suitable water, oxygen and temperature","Only bright paint","A metal container","A television signal"],"correct_option_index":0,"explanation":"Seeds typically germinate when conditions are suitable."},{"question":"How do earthworms often help gardens?","options":["They turn soil into plastic","They stop all microbes","They prevent all plant diseases","They improve soil structure as they move and feed"],"correct_option_index":3,"explanation":"Earthworm activity can support soil aeration and nutrient cycling."},{"question":"What is a greenhouse used for?","options":["Blocking all sunlight permanently","Replacing every farm worker","Managing growing conditions for plants","Storing fuel only"],"correct_option_index":2,"explanation":"Greenhouses let growers adjust aspects of the environment."},{"question":"Why should farmers check soil moisture?","options":["To choose the colour of baskets","To decide when plants need watering","To predict the next year''s prices exactly","To measure a tractor''s speed"],"correct_option_index":1,"explanation":"Soil moisture can guide irrigation decisions."},{"question":"What is an invasive pest?","options":["An organism that can harm crops outside its native balance","Every insect on a farm","A plant that gives fruit","A tool for harvesting rice"],"correct_option_index":0,"explanation":"Some introduced organisms cause damage when populations spread."},{"question":"Which crop is especially important as a staple food in Malaysia?","options":["Cocoa butter alone","Olives only","Rye bread alone","Rice"],"correct_option_index":3,"explanation":"Rice is a major staple food in Malaysia."},{"question":"What is a food supply chain?","options":["Only the final supermarket shelf","A type of cooking recipe","The stages from growing food to delivering it to consumers","A metal chain around a field"],"correct_option_index":2,"explanation":"Supply chains involve production, processing, transport and sales."},{"question":"What can happen when harvested vegetables are stored too warm?","options":["They become immune to bacteria","They may spoil more quickly","They become permanently sterile","Their mass always doubles"],"correct_option_index":1,"explanation":"Temperature control helps preserve freshness."},{"question":"What is hydroponics?","options":["Growing plants with nutrient solutions without conventional soil","Growing plants only in snow","Storing seeds in oil","A method of fishing"],"correct_option_index":0,"explanation":"Hydroponics supplies nutrients through water-based growing systems."},{"question":"Why might farmers use mulch around plants?","options":["To remove all oxygen from the air","To grow rocks","To stop sunlight reaching leaves","To reduce evaporation and suppress some weeds"],"correct_option_index":3,"explanation":"Mulch can protect soil moisture and moderate temperature."},{"question":"What is sustainable farming aiming to balance?","options":["Only the colour of fields","Maximum pesticide use always","Food production with long-term environmental and resource care","Harvest size at any environmental cost"],"correct_option_index":2,"explanation":"Sustainable methods aim to protect resources while producing food."},{"question":"Why can monoculture create risk for farms?","options":["It removes all costs","A single crop may be vulnerable to the same pest or disease","It always produces ten crops at once","It prevents every drought"],"correct_option_index":1,"explanation":"Low crop diversity can increase shared vulnerability."},{"question":"What is a natural predator used for in pest management?","options":["Helping control harmful insect populations","Adding salt to all soil","Removing all birds","Turning crops into fuel"],"correct_option_index":0,"explanation":"Biological control can use predators of crop pests."},{"question":"Which food waste practice can help a household garden?","options":["Mixing batteries into soil","Pouring engine oil on plants","Dumping plastic bags","Composting suitable plant scraps"],"correct_option_index":3,"explanation":"Suitable biodegradable scraps can become compost."},{"question":"What is the purpose of farm-to-market transport?","options":["Eliminate the need for packaging in every case","Change plant species","Deliver harvested food to buyers safely and efficiently","Make crops grow without sunlight"],"correct_option_index":2,"explanation":"Transport connects producers to processors, sellers and consumers."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000005","title":"Ocean Explorers: Life Beneath the Waves","subject":"Ocean Science","grade_level":"Year 6","language":"en","description":"20 original ocean questions on tides, reefs, marine life and science.","questions":[{"question":"What covers most of Earth''s surface?","options":["Oceans and seas","Desert dunes","Permanent ice sheets","Rainforests"],"correct_option_index":0,"explanation":"Ocean water covers about seventy-one percent of Earth''s surface."},{"question":"What causes most regular ocean tides?","options":["Wind direction only","Volcanic heat only","Rainfall in one city","The gravitational pull of the Moon, with a contribution from the Sun"],"correct_option_index":3,"explanation":"Lunar gravity dominates most tidal patterns."},{"question":"Why are coral reefs valuable?","options":["They prevent every tsunami","They replace ocean currents","They provide habitat for many marine species","They make all ocean water fresh"],"correct_option_index":2,"explanation":"Complex reefs shelter and support diverse organisms."},{"question":"What is a plankton organism?","options":["A submarine component","A drifting organism carried by water movement","Only a fully grown shark","A permanent rock"],"correct_option_index":1,"explanation":"Plankton includes small plants and animals that drift in water."},{"question":"What is phytoplankton''s role in marine food webs?","options":["It produces organic matter using light","It always eats whales","It destroys all oxygen","It is made of plastic"],"correct_option_index":0,"explanation":"Many phytoplankton species perform photosynthesis."},{"question":"Which zone of the ocean receives the most sunlight?","options":["The deepest trenches","The seabed everywhere","Under volcanic rocks only","Surface waters"],"correct_option_index":3,"explanation":"Light generally decreases as water depth increases."},{"question":"Why does ocean water taste salty?","options":["It has no minerals","It is mixed with sand only","It contains dissolved mineral salts","It is mostly sugar"],"correct_option_index":2,"explanation":"Weathering and other processes supply dissolved salts to the ocean."},{"question":"Which marine animal is a mammal?","options":["Sea star","Dolphin","Tuna","Octopus"],"correct_option_index":1,"explanation":"Dolphins breathe air and nurse their young."},{"question":"How do many fish obtain dissolved oxygen?","options":["Using gills","By growing leaves","Through wheels","By collecting sunlight in fur"],"correct_option_index":0,"explanation":"Fish gills exchange gases with surrounding water."},{"question":"What does a marine protected area try to do?","options":["Ban every research project","Turn seawater into fresh water","Remove all fishing boats worldwide","Conserve ocean habitats and species"],"correct_option_index":3,"explanation":"Protection rules can help preserve marine ecosystems."},{"question":"How can plastic litter affect sea turtles?","options":["Turtles have metal shells","Plastic makes water less salty","Turtles may mistake plastic for food or become entangled","Plastic always turns into food"],"correct_option_index":2,"explanation":"Ingestion and entanglement are serious risks."},{"question":"What is an estuary?","options":["An inland volcano","A place where river water mixes with seawater","A high mountain summit","A desert plateau"],"correct_option_index":1,"explanation":"Estuaries contain a changing mixture of fresh and salt water."},{"question":"Why do mangrove forests help young fish?","options":["Their roots create sheltered nursery habitats","Their roots produce unlimited salt","They stop all ocean waves","They are made only of coral"],"correct_option_index":0,"explanation":"Many juvenile fish use sheltered mangrove waters."},{"question":"What is sonar commonly used for?","options":["Measuring only sunlight","Changing seawater colour","Producing freshwater rain","Using sound waves to detect objects underwater"],"correct_option_index":3,"explanation":"Sound travels well underwater and can reveal submerged objects."},{"question":"What is the deep ocean usually like?","options":["Filled with sunlight at all depths","Completely free of life","Cold, dark and under high pressure","Bright and hot everywhere"],"correct_option_index":2,"explanation":"Deep water has little light and can have high pressure."},{"question":"What are ocean currents?","options":["Kinds of marine plants","Large-scale movements of seawater","Only surface bubbles","Underwater mountain ranges"],"correct_option_index":1,"explanation":"Currents transport water, heat and nutrients."},{"question":"What is a sustainable seafood choice concerned with?","options":["Avoiding unnecessary harm to fish populations and habitats","Buying only the biggest fish","Ignoring fishing methods","Catching every juvenile fish"],"correct_option_index":0,"explanation":"Fishing practices affect marine ecosystems and future stocks."},{"question":"Why can fertiliser runoff damage coastal water?","options":["Nutrients always remove algae","It makes all water drinkable","It stops tides","Excess nutrients may trigger harmful algal blooms"],"correct_option_index":3,"explanation":"Too many nutrients can cause blooms and oxygen problems."},{"question":"What is a scientific use of an underwater robot?","options":["Make waves disappear","Change the Earth''s gravity","Explore places difficult or dangerous for divers","Replace every marine animal"],"correct_option_index":2,"explanation":"Remotely operated vehicles collect images and measurements."},{"question":"How can students help protect nearby beaches?","options":["Damage coastal plants","Take litter home and join safe clean-up efforts","Leave fishing lines in the sand","Release plastic packaging into the sea"],"correct_option_index":1,"explanation":"Reducing litter helps protect coastal habitats."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000006","title":"Engineering Workshop: Build & Test","subject":"Engineering","grade_level":"Year 7","language":"en","description":"20 engineering design and physics questions about structures, testing and inventions.","questions":[{"question":"What is the first useful step in an engineering project?","options":["Buy random materials","Paint the final model","Skip all safety planning","Define the problem and requirements"],"correct_option_index":3,"explanation":"Clear requirements guide a practical design."},{"question":"Why do engineers build models?","options":["To avoid understanding forces","To replace every measurement","To test ideas before constructing full-size designs","To guarantee no mistakes"],"correct_option_index":2,"explanation":"Models help reveal strengths and weaknesses."},{"question":"Why are triangles common in bridge trusses?","options":["They cannot ever bend","They can form rigid structures that distribute loads","They remove the need for materials","They produce electricity automatically"],"correct_option_index":1,"explanation":"Triangular geometry can improve structural stability."},{"question":"What is a load in structural engineering?","options":["A force or weight acting on a structure","Only a paint colour","The length of a website","The price of a ticket"],"correct_option_index":0,"explanation":"A load is something a structure must support."},{"question":"What does a lever help a person do?","options":["Create energy from nothing","Remove all friction","Make every object weightless","Change the effort or direction needed to move a load"],"correct_option_index":3,"explanation":"Levers provide mechanical advantage in suitable arrangements."},{"question":"Why is a safety factor used in design?","options":["To make every structure heavier without purpose","To guarantee that nothing can fail","To account for uncertainty and unexpected stresses","To avoid following building rules"],"correct_option_index":2,"explanation":"Safety factors allow margins beyond expected loads."},{"question":"What is friction?","options":["A battery''s colour","A force resisting relative motion between surfaces","A type of sunlight","The absence of gravity"],"correct_option_index":1,"explanation":"Friction acts against sliding or attempted sliding."},{"question":"Which material is commonly used for electrical insulation?","options":["Rubber","Copper","Silver","Aluminium"],"correct_option_index":0,"explanation":"Rubber generally resists electrical current."},{"question":"Why does a bicycle need brakes?","options":["To accelerate endlessly","To turn into an aircraft","To eliminate gravity","To slow and stop through controlled friction"],"correct_option_index":3,"explanation":"Brakes dissipate motion energy, often as heat."},{"question":"What is a renewable energy engineering challenge?","options":["Removing the need for wiring","Creating power from nothing","Storing electricity when the wind is not blowing","Making sunlight permanently disappear"],"correct_option_index":2,"explanation":"Energy storage helps balance variable renewable generation."},{"question":"A bridge prototype bends too far in a test. What should the team do?","options":["Assume the model is perfect","Review the load path and revise its design","Hide the test results","Increase the weight without analysis"],"correct_option_index":1,"explanation":"Tests should inform design changes."},{"question":"What is the role of a gear?","options":["Transmit rotation and change speed or torque","Store only sound","Produce light without electricity","Remove the need for bearings"],"correct_option_index":0,"explanation":"Gears transfer turning motion between shafts."},{"question":"What does an engineer mean by an iteration?","options":["A design that can never change","A laboratory chemical","A list of unrelated parts","A revised version after learning from a test"],"correct_option_index":3,"explanation":"Iteration improves a design through repeated cycles."},{"question":"Why must drinking-water systems be carefully designed?","options":["To remove all pressure","To use only glass everywhere","To deliver water safely and reduce contamination risk","To maximise colour in the pipes"],"correct_option_index":2,"explanation":"Public water systems need safe treatment and distribution."},{"question":"What is a sensor in a robot?","options":["A software advertisement","A device that measures conditions or detects changes","Only a wheel","The robot''s logo"],"correct_option_index":1,"explanation":"Sensors supply information to a control system."},{"question":"Why is accessibility important in building design?","options":["People with different mobility and sensory needs should be able to use spaces","Only one body size should be considered","Doors should always be narrow","Stairs can replace every entrance"],"correct_option_index":0,"explanation":"Inclusive design aims to remove barriers."},{"question":"What does a pulley system do?","options":["Turn water into fuel","Measure only temperature","Remove every load","Change the direction of a force and sometimes reduce effort"],"correct_option_index":3,"explanation":"Pulleys can offer mechanical advantage."},{"question":"Why do engineers record measurements during tests?","options":["To avoid using evidence","To hide incorrect results","To compare actual performance with requirements","To make documentation longer only"],"correct_option_index":2,"explanation":"Recorded data supports evidence-based decisions."},{"question":"What is a trade-off in design?","options":["Safety can always be ignored","Improving one feature may require sacrificing another","Every solution is perfect","Cost never matters"],"correct_option_index":1,"explanation":"Designs must balance several competing requirements."},{"question":"Which action shows good workshop safety?","options":["Wear suitable eye protection and follow tool instructions","Use damaged wires without checking","Touch moving gears deliberately","Leave sharp tools on the floor"],"correct_option_index":0,"explanation":"Protective equipment and safe procedures reduce risk."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000007","title":"World Cultures & Traditions","subject":"World Cultures","grade_level":"Year 6","language":"en","description":"20 cross-cultural questions on languages, traditions, food and respectful exchange.","questions":[{"question":"Why is it useful to learn greetings in another language?","options":["It guarantees perfect pronunciation","It replaces all listening skills","It can help show respect and start conversations","It makes every person speak English"],"correct_option_index":2,"explanation":"Trying another language can build connection and respect."},{"question":"What does cultural diversity mean?","options":["All communities celebrating identical holidays","Different cultural practices and experiences existing together","Everyone having exactly the same traditions","Only one language being allowed"],"correct_option_index":1,"explanation":"Diversity describes variation among communities."},{"question":"Which Malaysian festival is widely associated with decorative kolam designs?","options":["Deepavali","Christmas","Hari Gawai","Chap Goh Mei"],"correct_option_index":0,"explanation":"Kolam patterns are often displayed for Deepavali celebrations."},{"question":"What is a common element of Chinese New Year celebrations?","options":["A compulsory beach race","Only eating bread","Always celebrating in July","Family reunions and visits"],"correct_option_index":3,"explanation":"Reunion meals and visits are important for many families."},{"question":"Which celebration marks the end of Ramadan for Muslims?","options":["Vesak Day","Christmas","Hari Raya Aidilfitri","Deepavali"],"correct_option_index":2,"explanation":"Aidilfitri follows the Ramadan fasting month."},{"question":"What does the term ''heritage'' often include?","options":["A single type of uniform","Traditions, objects and knowledge passed between generations","Only newly invented apps","Items that nobody remembers"],"correct_option_index":1,"explanation":"Cultural heritage can be tangible or intangible."},{"question":"Why should visitors ask before photographing a cultural ceremony?","options":["Some people or activities require permission and respect","Cameras always take better photos at night","Tourists own every image","All ceremonies are public property"],"correct_option_index":0,"explanation":"Asking helps respect privacy and local customs."},{"question":"What is an oral tradition?","options":["Only written laws","A type of computer storage","A machine that makes fabric","Stories or knowledge shared through speaking"],"correct_option_index":3,"explanation":"Communities can pass knowledge verbally."},{"question":"Which instrument is associated with the Malaysian gamelan tradition?","options":["Tuba only","Electric guitar only","Gong","Bagpipe only"],"correct_option_index":2,"explanation":"Gamelan ensembles use instruments including gongs and metallophones."},{"question":"What does a traditional recipe often teach about a place?","options":["The length of all rivers","Local ingredients, history and customs","The exact weather next year","Every person''s favourite sport"],"correct_option_index":1,"explanation":"Food reflects resources, migration and community practices."},{"question":"Why is respectful disagreement important in intercultural discussions?","options":["People may have different beliefs and experiences","Every tradition must be identical","Disagreement is always unsafe","Listening has no value"],"correct_option_index":0,"explanation":"Respectful dialogue allows different perspectives."},{"question":"What is an example of intangible cultural heritage?","options":["A concrete bridge only","A single office printer","A plastic chair alone","A traditional dance performed across generations"],"correct_option_index":3,"explanation":"Performances and skills can be intangible heritage."},{"question":"What is a ''dialect'' in language?","options":["A type of musical key","A brand of keyboard","A regional or social variety of a language","A language that cannot be spoken"],"correct_option_index":2,"explanation":"Dialects vary in pronunciation, vocabulary or grammar."},{"question":"Which festival is celebrated in parts of Sabah by Kadazan-Dusun communities?","options":["Hanami","Kaamatan","Oktoberfest","Mardi Gras"],"correct_option_index":1,"explanation":"Kaamatan is associated with harvest celebrations in Sabah."},{"question":"What is a cultural stereotype?","options":["An oversimplified belief about a whole group","A reliable description of every individual","A recipe instruction","A verified historical date"],"correct_option_index":0,"explanation":"Stereotypes ignore differences between individuals."},{"question":"Why should museums describe where artefacts came from?","options":["Objects have no histories","Exhibits never need explanations","Labels always replace research","Provenance provides historical and ethical context"],"correct_option_index":3,"explanation":"Provenance helps explain origins and ownership."},{"question":"What does bilingual mean?","options":["Speaking without listening","Never learning a native language","Able to use two languages","Knowing only two words"],"correct_option_index":2,"explanation":"Bilingual people use two languages to varying degrees."},{"question":"What can music across cultures reveal?","options":["That songs contain no history","Different rhythms, instruments and social functions","That every song has the same beat","That culture never changes"],"correct_option_index":1,"explanation":"Music expresses creativity and community traditions."},{"question":"Which practice supports cultural exchange?","options":["Listening, asking respectful questions and sharing knowledge","Mocking unfamiliar customs","Assuming one culture is superior","Refusing translation help"],"correct_option_index":0,"explanation":"Exchange works better with curiosity and mutual respect."},{"question":"Why might a traditional craft be taught to younger people?","options":["To prevent all modern design","To stop people learning other crafts","To remove its cultural meaning","To preserve skills and allow creative adaptation"],"correct_option_index":3,"explanation":"Transmission can sustain heritage while allowing change."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000008","title":"Communities, Citizenship & Public Services","subject":"Civics","grade_level":"Year 7","language":"en","description":"20 non-partisan questions about communities, public services, shared rules and responsibility.","questions":[{"question":"What is the purpose of a public library?","options":["Replace every school","Provide access to books, information and learning resources","Sell only luxury goods","Keep all books private"],"correct_option_index":1,"explanation":"Libraries support education and community access."},{"question":"Why do communities have traffic rules?","options":["To reduce crashes and coordinate road use","To make journeys randomly longer","To prevent all walking","To ban every bicycle"],"correct_option_index":0,"explanation":"Shared rules improve predictability and safety."},{"question":"What does ''public service'' commonly refer to?","options":["Only a private birthday party","A personal game account","A fictional business name","Services intended to benefit the community"],"correct_option_index":3,"explanation":"Public services support shared needs."},{"question":"Why should school rules be clear and accessible?","options":["Only teachers need to know them","Clarity is not important","Students can understand expectations and apply them fairly","Rules should be secret"],"correct_option_index":2,"explanation":"Clear rules help people act consistently."},{"question":"What is volunteering?","options":["Secretly sharing passwords","Giving time or effort to help others without expecting wages","Borrowing money at high interest","Only buying products"],"correct_option_index":1,"explanation":"Volunteers support community activities."},{"question":"Why are emergency exits clearly marked?","options":["People need a route to safety during an emergency","To advertise nearby shops","To make corridors darker","To replace building maps for all uses"],"correct_option_index":0,"explanation":"Visible exit signs assist evacuation."},{"question":"What is a community consultation?","options":["A replacement for all laws","A private password exchange","A fixed school examination","An opportunity for residents to share views on a proposal"],"correct_option_index":3,"explanation":"Consultations collect perspectives on decisions."},{"question":"How should a disagreement about a shared playground be handled?","options":["Threaten other children","Ignore every concern","Discuss needs and seek a fair practical solution","Damage the playground"],"correct_option_index":2,"explanation":"Listening and compromise can resolve shared-space disputes."},{"question":"Why do towns collect household waste?","options":["To replace recycling with dumping everywhere","To maintain sanitation and manage materials safely","To increase litter","To block public roads"],"correct_option_index":1,"explanation":"Waste services reduce public health and environmental risks."},{"question":"What is a pedestrian crossing for?","options":["Helping people cross roads in a designated place","Marking a racing track","Parking vehicles permanently","Storing bicycles"],"correct_option_index":0,"explanation":"Crossings organise vehicle and pedestrian movement."},{"question":"Which practice shows responsible digital citizenship?","options":["Publish private messages for attention","Create false accounts to harass classmates","Spread unverified rumours","Respect others and avoid sharing private information without permission"],"correct_option_index":3,"explanation":"Good digital citizenship combines respect and privacy."},{"question":"Why are local parks important?","options":["They produce all drinking water","They replace every forest","They can offer recreation and support urban nature","They guarantee every city has identical weather"],"correct_option_index":2,"explanation":"Parks provide opportunities for play and green space."},{"question":"What does fairness in a classroom involve?","options":["Ignoring everyone with disabilities","Applying rules consistently while considering relevant needs","Giving prizes only to friends","Changing rules secretly"],"correct_option_index":1,"explanation":"Fair decisions need consistency and reasonable accommodation."},{"question":"What is a useful way to report a broken streetlight?","options":["Notify the appropriate local service with its location","Damage more lights","Post a classmate''s password","Invent an emergency"],"correct_option_index":0,"explanation":"Accurate reports help services identify the problem."},{"question":"What is a local community group?","options":["A single isolated machine","Only a national government","An online advertisement alone","People cooperating around a shared neighbourhood or interest"],"correct_option_index":3,"explanation":"Groups coordinate activities and mutual support."},{"question":"Why should public information be written clearly?","options":["Only experts use public facilities","Translation is never useful","Residents need to understand services and instructions","Confusing words improve safety"],"correct_option_index":2,"explanation":"Accessible language helps more people use information."},{"question":"What should someone do if they find a lost wallet at school?","options":["Hide it in a locker","Give it to a trusted staff member","Keep the cash","Publish identifying details online"],"correct_option_index":1,"explanation":"Staff can handle lost property safely."},{"question":"Why is listening important in group decisions?","options":["It helps reveal needs and concerns that others may have","It always guarantees agreement","It makes evidence irrelevant","It removes all rules"],"correct_option_index":0,"explanation":"Listening can lead to more informed decisions."},{"question":"What is a shared community resource?","options":["Only an individual password","A locked private diary","Someone else''s bank card","Something residents use or benefit from together"],"correct_option_index":3,"explanation":"Libraries, parks and pathways are examples of shared resources."},{"question":"Which action demonstrates care for public facilities?","options":["Leave taps running unnecessarily","Break safety signs","Use equipment responsibly and report damage","Carve names into school desks"],"correct_option_index":2,"explanation":"Responsible use helps facilities remain available to others."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000009","title":"Food, Cooking & Everyday Nutrition","subject":"Food & Nutrition","grade_level":"Year 6","language":"en","description":"20 questions on food safety, cooking skills, balanced meals and nutrition basics.","questions":[{"question":"Why should hands be washed before preparing food?","options":["To reduce the spread of microbes to food","To change the food''s flavour","To increase the water content of fruit","To make knives sharper"],"correct_option_index":0,"explanation":"Clean hands lower the chance of transferring harmful microbes."},{"question":"What is a balanced meal?","options":["Only sweets and drinks","The largest possible meal","A plate containing one food only","A meal including varied food groups in suitable proportions"],"correct_option_index":3,"explanation":"Variety helps provide different nutrients."},{"question":"Which nutrient is an important source of energy?","options":["Sand","Glass","Carbohydrates","Plastic"],"correct_option_index":2,"explanation":"Carbohydrates are one source of energy for the body."},{"question":"What is protein useful for?","options":["Making bones invisible","Growth and repair of body tissues","Replacing the need for water","Preventing all diseases"],"correct_option_index":1,"explanation":"Protein supplies amino acids used to build and repair tissues."},{"question":"What do dietary fibres help support?","options":["Normal digestion and bowel function","Instant muscle growth","Screen vision only","Replacing sleep"],"correct_option_index":0,"explanation":"Fibre supports digestive health."},{"question":"Why is clean drinking water important?","options":["It has no role in digestion","It replaces every food nutrient","It makes people never tired","It helps the body stay hydrated"],"correct_option_index":3,"explanation":"Water is essential for many normal body processes."},{"question":"Which method best lowers the risk of cross-contamination?","options":["Touch cooked food after handling raw meat without washing","Store raw chicken above fresh salad","Use separate tools or clean them between raw meat and ready-to-eat food","Use one dirty board for all ingredients"],"correct_option_index":2,"explanation":"Separation and cleaning reduce transfer of harmful microorganisms."},{"question":"Why should raw poultry be cooked thoroughly?","options":["To make storage unnecessary","To reduce foodborne infection risk","To make it weigh exactly twice as much","To remove all vitamins"],"correct_option_index":1,"explanation":"Adequate cooking destroys many dangerous microorganisms."},{"question":"Why should foods be stored at appropriate temperatures?","options":["To slow harmful microbial growth and spoilage","To change every food into ice","To remove the need to wash produce","To make expiry dates irrelevant"],"correct_option_index":0,"explanation":"Temperature control is a key part of food safety."},{"question":"What does a food ingredient list show?","options":["The name of every customer","Only the company''s advertising slogan","The future weather forecast","Ingredients used to make a packaged product"],"correct_option_index":3,"explanation":"Ingredient lists help consumers understand what is in a product."},{"question":"Which is a healthy approach to eating?","options":["Eat the same snack for every meal","Avoid drinking water","Choose varied foods and listen to hunger and fullness cues","Skip all meals to study longer"],"correct_option_index":2,"explanation":"Balanced eating and routine habits support health."},{"question":"Why can home cooking be a useful skill?","options":["It replaces safe knife practices","It helps people plan ingredients, hygiene and portion choices","It guarantees all meals are perfect","It eliminates all grocery costs"],"correct_option_index":1,"explanation":"Cooking skills support informed food preparation."},{"question":"What are legumes?","options":["Plants such as beans, peas and lentils","Only kinds of fish","Types of kitchen knives","A form of bottled water"],"correct_option_index":0,"explanation":"Legumes are edible seeds from plants in the legume family."},{"question":"Which food group commonly provides calcium?","options":["Cooking oil alone","White sugar alone","Plain table salt","Milk, yoghurt or fortified alternatives"],"correct_option_index":3,"explanation":"Dairy and some fortified alternatives can contribute calcium."},{"question":"What is a recipe''s ingredient quantity for?","options":["Showing only cooking temperature","Advertising the kitchen","Measuring what is needed to prepare a dish","Determining the cook''s age"],"correct_option_index":2,"explanation":"Correct quantities improve consistency and reduce waste."},{"question":"A recipe serves four people. For eight people, what should you usually do to ingredient amounts?","options":["Keep every ingredient unchanged","Double the ingredients","Halve the ingredients","Use no ingredients"],"correct_option_index":1,"explanation":"Doubling servings generally doubles ingredient quantities."},{"question":"Why should vegetables be washed before eating?","options":["To remove some dirt and surface contamination","To turn them into fruit","To eliminate the need for safe storage","To add protein to every vegetable"],"correct_option_index":0,"explanation":"Washing can remove soil and some contaminants."},{"question":"What is food waste?","options":["Only empty packaging","Every compost pile","Only food in restaurants","Food intended for consumption that is discarded"],"correct_option_index":3,"explanation":"Wasted food uses resources without being eaten."},{"question":"Which method helps reduce food waste at home?","options":["Discard food before checking it","Ignore storage instructions","Plan portions and safely use leftovers","Buy more than you can store"],"correct_option_index":2,"explanation":"Planning and proper storage reduce unnecessary waste."},{"question":"Why is the nutrition information panel useful?","options":["It tells you who bought the food","It helps compare energy and nutrient amounts across foods","It proves every product is healthy","It replaces medical advice"],"correct_option_index":1,"explanation":"Nutrition panels provide standardised information for comparison."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000010","title":"Weather Watchers & Climate Patterns","subject":"Weather","grade_level":"Year 6","language":"en","description":"20 questions on clouds, rainfall, forecasts and safe weather awareness.","questions":[{"question":"What instrument measures rainfall amount?","options":["Compass","Stopwatch","Balance scale","Rain gauge"],"correct_option_index":3,"explanation":"A rain gauge collects rainfall to measure its depth."},{"question":"What is air pressure?","options":["The number of clouds only","The size of a mountain","The force of air acting over an area","The colour of a rainbow"],"correct_option_index":2,"explanation":"Air has mass and exerts pressure."},{"question":"What does an anemometer measure?","options":["Water depth","Wind speed","Soil acidity","Earthquake magnitude"],"correct_option_index":1,"explanation":"Anemometers are used to measure wind speed."},{"question":"How do many clouds form?","options":["Water vapour cools and condenses into droplets or ice crystals","The ocean turns into smoke","Mountains release cotton","Sunlight becomes sand"],"correct_option_index":0,"explanation":"Condensation produces droplets and crystals suspended in air."},{"question":"What is humidity?","options":["The number of birds in a tree","The strength of a compass","The colour of soil","The amount of water vapour in the air"],"correct_option_index":3,"explanation":"Humidity describes atmospheric water vapour."},{"question":"What is the main difference between weather and climate?","options":["They are identical terms","Climate describes only today''s rain","Weather is short-term conditions; climate is long-term patterns","Weather lasts centuries; climate lasts one minute"],"correct_option_index":2,"explanation":"Climate is described using longer-term statistics of weather."},{"question":"What causes a rainbow?","options":["Only lightning","Sunlight refracting, reflecting and dispersing in water droplets","Clouds producing coloured paint","Air becoming solid"],"correct_option_index":1,"explanation":"Light interacts with droplets to create a spectrum."},{"question":"What is a thunderstorm?","options":["A storm with lightning and thunder","Any quiet sunny day","A type of ocean current","An eclipse of the Moon"],"correct_option_index":0,"explanation":"Electrical activity in storm clouds causes lightning."},{"question":"During nearby lightning, what is the safest general place to be?","options":["Under a lone tall tree","On an open sports field","Swimming in a lake","Inside a substantial building"],"correct_option_index":3,"explanation":"Indoor shelter is safer during lightning."},{"question":"Why can steep slopes be dangerous after heavy rain?","options":["Gravity stops acting","The soil becomes weightless","Water may destabilise soil and contribute to landslides","Rain always makes mountains taller"],"correct_option_index":2,"explanation":"Saturated ground can increase slope failure risk."},{"question":"What does a weather forecast estimate?","options":["Which song will be popular tomorrow","Likely atmospheric conditions over a period","Exact weather with perfect certainty","The age of every tree"],"correct_option_index":1,"explanation":"Forecasts use observations and models to estimate future conditions."},{"question":"Which measurement describes temperature?","options":["Degrees Celsius","Kilograms per second","Metres per litre","Newtons per minute"],"correct_option_index":0,"explanation":"Temperature is commonly measured in Celsius."},{"question":"What is the monsoon?","options":["A type of insect","A daily ocean tide","A bright star","A seasonal pattern of winds associated with rainfall changes"],"correct_option_index":3,"explanation":"Monsoon circulations influence seasonal rainfall in many regions."},{"question":"Why do meteorologists use weather satellites?","options":["To create sunlight","To replace all ground measurements","To observe cloud patterns and atmospheric features","To directly change every storm"],"correct_option_index":2,"explanation":"Satellite data supplements surface observations."},{"question":"Why are storm drains important in cities?","options":["They turn rivers into roads","They carry away excess surface water when functioning properly","They make rainfall stop","They increase every flood risk automatically"],"correct_option_index":1,"explanation":"Drainage systems manage runoff, within design limits."},{"question":"What is evaporation in the water cycle?","options":["Liquid water becoming vapour","Clouds freezing into rock","Rain becoming electricity","Wind turning into water"],"correct_option_index":0,"explanation":"Evaporation moves water from surfaces into the air."},{"question":"What is a drought?","options":["One short rain shower","A period of excess flooding everywhere","Any day with clouds","A prolonged period of unusually low water availability"],"correct_option_index":3,"explanation":"Drought reflects extended water shortages."},{"question":"Why are heat warnings useful?","options":["They replace drinking water","They guarantee cool weather","They help people plan hydration, shade and reduced heat exposure","They prevent every hot day"],"correct_option_index":2,"explanation":"Heat advisories communicate elevated heat risk."},{"question":"What makes a sea breeze more likely during daytime near the coast?","options":["All winds suddenly disappearing","Land heating more quickly than nearby sea water","The sea completely stopping waves","The Moon becoming brighter"],"correct_option_index":1,"explanation":"Uneven heating can create local air circulation."},{"question":"Why should a school have a weather emergency plan?","options":["To guide safe shelter, communications and activities","To ensure there will never be storms","To stop teachers using maps","To replace normal lessons permanently"],"correct_option_index":0,"explanation":"Prepared procedures help people respond effectively."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000011","title":"Wildlife, Habitats & Biodiversity","subject":"Animals & Nature","grade_level":"Year 6","language":"en","description":"20 questions about animal adaptations, habitats, conservation and ecosystems.","questions":[{"question":"In conservation science, what does biodiversity describe?","options":["Only one tree species","A type of electrical circuit","The variety of living organisms and ecological systems","The number of buildings in a city"],"correct_option_index":2,"explanation":"Biodiversity includes species, genetic and ecosystem diversity."},{"question":"In wildlife ecology, what does the term habitat mean?","options":["A laboratory temperature scale","The natural place where an organism lives","Only a type of zoo ticket","A single television programme"],"correct_option_index":1,"explanation":"Habitats provide resources and conditions for organisms."},{"question":"Why do birds have different beak shapes?","options":["They are adapted for different foods and ways of feeding","All birds eat the same seeds","Beaks never change across species","Beaks measure rainfall"],"correct_option_index":0,"explanation":"Beak form is linked to diet and ecological role."},{"question":"What is camouflage?","options":["A type of artificial intelligence model","A form of musical notation","A replacement for breathing","Features that help an organism blend with surroundings"],"correct_option_index":3,"explanation":"Camouflage can make animals harder to detect."},{"question":"What is a nocturnal animal?","options":["A plant that floats","A fish that never swims","An animal active mainly at night","An animal with no bones"],"correct_option_index":2,"explanation":"Nocturnal species are primarily active after dark."},{"question":"What is migration in animals?","options":["A kind of photosynthesis","Seasonal movement between regions","Changing a computer password","Every movement within one cage"],"correct_option_index":1,"explanation":"Migration can follow seasonal food and breeding opportunities."},{"question":"Which animal is an amphibian?","options":["Frog","Eagle","Butterfly","Earthworm"],"correct_option_index":0,"explanation":"Frogs are amphibians with life stages linked to water and land."},{"question":"What is an invertebrate?","options":["An animal with feathers only","A plant with roots","A large mammal only","An animal without a backbone"],"correct_option_index":3,"explanation":"Invertebrates include insects, molluscs and many other groups."},{"question":"Why are wetlands valuable?","options":["They prevent every drought","They are always dry","They provide habitat, filter some pollutants and store water","They contain no living organisms"],"correct_option_index":2,"explanation":"Wetlands support biodiversity and water regulation."},{"question":"What can happen if an important pollinator declines?","options":["No flowering plant can reproduce at all","Some plants may produce fewer fruits or seeds","All crops instantly stop growing","Every fish disappears"],"correct_option_index":1,"explanation":"Many plants benefit from animal pollination."},{"question":"What is an endangered species?","options":["A species facing a high risk of extinction","A species that is always common","Any pet that is sleepy","A newly planted flower"],"correct_option_index":0,"explanation":"Endangered classifications reflect elevated extinction risk."},{"question":"What does a conservation programme try to do?","options":["Replace every wild animal with a robot","Remove all native plants","Make all forests identical","Protect species, habitats or natural resources"],"correct_option_index":3,"explanation":"Conservation aims to sustain ecosystems and species."},{"question":"Why should wild animals not be fed unfamiliar human foods?","options":["It guarantees more biodiversity","All human food is suitable for wildlife","It may harm their health and natural behaviour","It always makes them immortal"],"correct_option_index":2,"explanation":"Feeding wildlife can introduce poor diets and dependence."},{"question":"What is a keystone species?","options":["Any tree older than ten years","A species whose influence on its ecosystem is unusually large","Only the largest animal in a zoo","An organism living only in caves"],"correct_option_index":1,"explanation":"Some species strongly shape ecosystem interactions."},{"question":"Why are connected wildlife corridors useful?","options":["They help animals move between fragmented habitats","They block every migration route","They create new oceans","They replace all protected forests"],"correct_option_index":0,"explanation":"Corridors can maintain movement and genetic exchange."},{"question":"When studying an ecosystem, what does a food chain show?","options":["A metal chain used in farming","A plan for cooking lessons","A list of weather stations","A simple sequence showing who eats whom"],"correct_option_index":3,"explanation":"Food chains represent the transfer of energy through feeding."},{"question":"What is an invasive species?","options":["A species found in its original home","A plant that always produces flowers","A non-native organism that spreads and causes ecological harm","Any animal in a nature reserve"],"correct_option_index":2,"explanation":"Some introduced species can damage native ecosystems."},{"question":"Why do some animals have thick fur in cold environments?","options":["It generates all sunlight","It can help reduce heat loss","It makes them weightless","It prevents the need for food"],"correct_option_index":1,"explanation":"Insulating fur helps maintain body temperature."},{"question":"What is an example of symbiosis?","options":["Two different species living in close ecological association","A thunderstorm moving across a city","A robot charging a battery","A single rock breaking apart"],"correct_option_index":0,"explanation":"Symbiosis refers to close interactions between distinct species."},{"question":"Which activity helps protect local wildlife?","options":["Collect every wild egg","Release unwanted pets into forests","Leave fishing lines in rivers","Respect habitats and avoid disturbing nests"],"correct_option_index":3,"explanation":"Reducing disturbance protects animals and habitat."}]},{"id":"c8202611-05b0-4a9b-9f00-000000000012","title":"Critical Thinking & Smart Decisions","subject":"Critical Thinking","grade_level":"Year 7","language":"en","description":"20 scenarios about reasoning, evaluating evidence, probability and thoughtful choices.","questions":[{"question":"A friend says ''everyone likes this game''. What should you ask?","options":["Can the game have more colours?","What evidence supports ''everyone''?","How loud can the claim be repeated?","Who has the biggest phone?"],"correct_option_index":1,"explanation":"Broad claims need evidence about the relevant group."},{"question":"What is a logical conclusion?","options":["A claim that follows from evidence and reasoning","A random guess stated confidently","Any rumour with a picture","A sentence with many emojis"],"correct_option_index":0,"explanation":"Sound conclusions are supported by relevant reasons."},{"question":"A study shows two events happen together. What does that prove by itself?","options":["One must cause the other","Both are always accidental","The study is automatically false","They are associated, not necessarily that one causes the other"],"correct_option_index":3,"explanation":"Correlation alone does not establish causation."},{"question":"Which is the best question when solving a problem?","options":["Can we skip collecting information?","How can we make the problem sound bigger?","What exactly is the problem we need to solve?","Who should we blame first?"],"correct_option_index":2,"explanation":"Clear problem definitions guide solutions."},{"question":"You hear two conflicting claims. What is a good next step?","options":["Share both as certain facts","Check evidence and the reliability of each source","Choose the louder speaker","Accept whichever seems more exciting"],"correct_option_index":1,"explanation":"Evidence quality matters more than confidence."},{"question":"Which is an example of a testable prediction?","options":["If plants receive less water, their growth may change","This plant is the prettiest ever","Everyone must enjoy gardening","The colour green is always best"],"correct_option_index":0,"explanation":"A prediction is testable when observations can support or challenge it."},{"question":"What is an assumption?","options":["A measured temperature","A verified receipt","A recorded observation only","An idea accepted without being directly established in the argument"],"correct_option_index":3,"explanation":"Assumptions can influence reasoning and should be examined."},{"question":"Why is it useful to consider an alternative explanation?","options":["It removes the need for testing","It makes all explanations identical","It can reveal whether the first explanation is sufficient","It guarantees the first idea is wrong"],"correct_option_index":2,"explanation":"Competing hypotheses help test reasoning."},{"question":"A claim uses only one success story to promise results for everyone. What is the weakness?","options":["No examples can be useful","One example may not represent a wider group","All personal stories are false","Success is impossible to measure"],"correct_option_index":1,"explanation":"Anecdotes do not establish general outcomes."},{"question":"What is a fair comparison in an experiment?","options":["Change one main variable while controlling other relevant conditions","Change every variable at once","Hide the control group","Report only favourite results"],"correct_option_index":0,"explanation":"Controlling conditions helps isolate effects."},{"question":"Why use a checklist for a complex task?","options":["It automatically completes the task","It removes all uncertainty","It guarantees no item will ever change","It helps avoid forgetting important steps"],"correct_option_index":3,"explanation":"Checklists support consistency and memory."},{"question":"A shop offers ''buy two, get one free''. What should you check?","options":["The background music","The number of stars in the logo","Whether you need three items and the total cost","Only the word ''free''"],"correct_option_index":2,"explanation":"An offer is useful only if it fits real needs and budget."},{"question":"What is a decision criterion?","options":["An unrelated slogan","A standard used to compare possible choices","A random preference not recorded","A secret password"],"correct_option_index":1,"explanation":"Criteria clarify what matters for a choice."},{"question":"Why do scientists report limitations of a study?","options":["To explain uncertainty and where results may not apply","To invalidate every result automatically","To avoid peer review","To make the title longer"],"correct_option_index":0,"explanation":"Limitations help readers interpret results appropriately."},{"question":"What is an example of circular reasoning?","options":["The measured length is 5 cm","The receipt lists three items","The plant grew 2 cm","This claim is true because it is correct"],"correct_option_index":3,"explanation":"Circular reasoning assumes what it claims to prove."},{"question":"What is a counterexample?","options":["A type of questionnaire","A random nickname","An instance that challenges a general claim","An example supporting every rule"],"correct_option_index":2,"explanation":"One valid counterexample can disprove a universal statement."},{"question":"A forecast says a 30% chance of rain. What does it communicate?","options":["There is no uncertainty","Rain is possible but not certain in the forecast conditions","Rain must happen for 30 minutes","Rain will cover exactly 30% of each road"],"correct_option_index":1,"explanation":"Probability estimates likelihood, not guaranteed outcomes."},{"question":"Why should a group identify constraints before designing a solution?","options":["Time, budget and safety limits affect what is feasible","Constraints never affect choices","Planning can ignore materials","Every idea costs the same"],"correct_option_index":0,"explanation":"Constraints shape realistic options."},{"question":"When an unexpected result appears, what is a responsible response?","options":["Delete it without explanation","Change the data to match your theory","Assume all instruments are broken","Check measurements and investigate possible causes"],"correct_option_index":3,"explanation":"Unexpected evidence deserves careful analysis."},{"question":"Which approach helps a team make a balanced decision?","options":["Ignore future effects","Count only positive comments","Compare benefits, risks and evidence before choosing","Ask only one person to decide secretly"],"correct_option_index":2,"explanation":"Balanced decisions consider multiple relevant factors."}]}]'::jsonb AS packs), expanded AS (
  SELECT p.value AS pack,q.value AS question,(q.ordinality-1)::integer AS position
  FROM bundle CROSS JOIN LATERAL jsonb_array_elements(bundle.packs) AS p(value)
  CROSS JOIN LATERAL jsonb_array_elements(p.value->'questions') WITH ORDINALITY AS q(value,ordinality)
)
INSERT INTO public.questions(quiz_set_id,position,question,choices,correct_index,explanation)
SELECT (e.pack->>'id')::uuid,e.position,e.question->>'question',e.question->'options',
  (e.question->>'correct_option_index')::smallint,e.question->>'explanation'
FROM expanded e JOIN public.quiz_sets s
 ON s.id=(e.pack->>'id')::uuid AND s.title=e.pack->>'title'
 AND s.owner_user_id IS NULL AND s.status='published'
WHERE NOT EXISTS (SELECT 1 FROM public.questions previous WHERE previous.quiz_set_id=s.id AND previous.position=e.position);
DO $zokivo$
DECLARE count_sets integer; count_items integer; uneven integer; bad_answers integer;
BEGIN
 SELECT count(*) INTO count_sets FROM public.quiz_sets WHERE id IN ('c8202611-05b0-4a9b-9f00-000000000001'::uuid,'c8202611-05b0-4a9b-9f00-000000000002'::uuid,'c8202611-05b0-4a9b-9f00-000000000003'::uuid,'c8202611-05b0-4a9b-9f00-000000000004'::uuid,'c8202611-05b0-4a9b-9f00-000000000005'::uuid,'c8202611-05b0-4a9b-9f00-000000000006'::uuid,'c8202611-05b0-4a9b-9f00-000000000007'::uuid,'c8202611-05b0-4a9b-9f00-000000000008'::uuid,'c8202611-05b0-4a9b-9f00-000000000009'::uuid,'c8202611-05b0-4a9b-9f00-000000000010'::uuid,'c8202611-05b0-4a9b-9f00-000000000011'::uuid,'c8202611-05b0-4a9b-9f00-000000000012'::uuid) AND status='published' AND owner_user_id IS NULL;
 SELECT count(*) INTO count_items FROM public.questions WHERE quiz_set_id IN ('c8202611-05b0-4a9b-9f00-000000000001'::uuid,'c8202611-05b0-4a9b-9f00-000000000002'::uuid,'c8202611-05b0-4a9b-9f00-000000000003'::uuid,'c8202611-05b0-4a9b-9f00-000000000004'::uuid,'c8202611-05b0-4a9b-9f00-000000000005'::uuid,'c8202611-05b0-4a9b-9f00-000000000006'::uuid,'c8202611-05b0-4a9b-9f00-000000000007'::uuid,'c8202611-05b0-4a9b-9f00-000000000008'::uuid,'c8202611-05b0-4a9b-9f00-000000000009'::uuid,'c8202611-05b0-4a9b-9f00-000000000010'::uuid,'c8202611-05b0-4a9b-9f00-000000000011'::uuid,'c8202611-05b0-4a9b-9f00-000000000012'::uuid);
 SELECT count(*) INTO uneven FROM (
  SELECT quiz_set_id,count(*) AS n FROM public.questions WHERE quiz_set_id IN ('c8202611-05b0-4a9b-9f00-000000000001'::uuid,'c8202611-05b0-4a9b-9f00-000000000002'::uuid,'c8202611-05b0-4a9b-9f00-000000000003'::uuid,'c8202611-05b0-4a9b-9f00-000000000004'::uuid,'c8202611-05b0-4a9b-9f00-000000000005'::uuid,'c8202611-05b0-4a9b-9f00-000000000006'::uuid,'c8202611-05b0-4a9b-9f00-000000000007'::uuid,'c8202611-05b0-4a9b-9f00-000000000008'::uuid,'c8202611-05b0-4a9b-9f00-000000000009'::uuid,'c8202611-05b0-4a9b-9f00-000000000010'::uuid,'c8202611-05b0-4a9b-9f00-000000000011'::uuid,'c8202611-05b0-4a9b-9f00-000000000012'::uuid)
  GROUP BY quiz_set_id HAVING count(*)<>20
 ) x;
 SELECT count(*) INTO bad_answers FROM public.questions WHERE quiz_set_id IN ('c8202611-05b0-4a9b-9f00-000000000001'::uuid,'c8202611-05b0-4a9b-9f00-000000000002'::uuid,'c8202611-05b0-4a9b-9f00-000000000003'::uuid,'c8202611-05b0-4a9b-9f00-000000000004'::uuid,'c8202611-05b0-4a9b-9f00-000000000005'::uuid,'c8202611-05b0-4a9b-9f00-000000000006'::uuid,'c8202611-05b0-4a9b-9f00-000000000007'::uuid,'c8202611-05b0-4a9b-9f00-000000000008'::uuid,'c8202611-05b0-4a9b-9f00-000000000009'::uuid,'c8202611-05b0-4a9b-9f00-000000000010'::uuid,'c8202611-05b0-4a9b-9f00-000000000011'::uuid,'c8202611-05b0-4a9b-9f00-000000000012'::uuid)
 AND (correct_index NOT BETWEEN 0 AND 3 OR jsonb_typeof(choices)<>'array'
 OR jsonb_array_length(choices)<>4 OR length(trim(question))<4 OR length(trim(explanation))<12);
 IF count_sets<>12 OR count_items<>240 OR uneven<>0 OR bad_answers<>0 THEN
  RAISE EXCEPTION 'ZoKivo cross-disciplinary QA mismatch sets %, items %, uneven %, bad %',count_sets,count_items,uneven,bad_answers;
 END IF;
END
$zokivo$;
COMMIT;
